/**
 * Form Builder Plugin Types
 *
 * Key distinction from CMS Plugin:
 * - CMS uses developer-defined Zod schemas in code
 * - Form Builder allows non-technical admins to build forms via drag-and-drop UI
 * - Forms are serialized to/from JSON Schema for storage
 */
import type { DeepReadonly } from "@btst/stack/plugins/api";
import type { PermissionFactsFor } from "@btst/stack/authorization";
import type { StackIdentity } from "@btst/stack/context";
import type { formBuilderPermissions } from "./permissions";
import type {
	CreateFormInput,
	ListFormsQuery,
	ListSubmissionsQuery,
	SubmitFormInput,
	UpdateFormInput,
} from "./schemas";

/**
 * Form stored in the database
 */
export type Form = {
	id: string;
	/** Display name for the form */
	name: string;
	/** URL-friendly slug - unique identifier for public access */
	slug: string;
	/** Optional description for admin UI */
	description?: string;
	/** JSON Schema stored as string (includes steps, fieldType, stepGroup, etc.) */
	schema: string;
	/** Optional custom success message after submission */
	successMessage?: string;
	/** Optional redirect URL after submission */
	redirectUrl?: string;
	/** Form status: active, inactive, archived */
	status: "active" | "inactive" | "archived";
	/** User who created the form */
	createdBy?: string;
	createdAt: Date;
	updatedAt: Date;
};

/**
 * Form submission stored in the database
 */
export type FormSubmission = {
	id: string;
	/** Reference to the form */
	formId: string;
	/** Submitted data as JSON string */
	data: string;
	/** Submission timestamp */
	submittedAt: Date;
	/** Optional user ID if authenticated */
	submittedBy?: string;
	/** Client IP address for rate limiting and spam protection */
	ipAddress?: string;
	/** User agent for analytics */
	userAgent?: string;
};

/**
 * Form submission with its parent form joined
 */
export type FormSubmissionWithForm = FormSubmission & {
	form?: Form;
};

/**
 * Serialized form for API responses (dates as strings)
 */
export interface SerializedForm
	extends Omit<Form, "createdAt" | "updatedAt" | "status"> {
	status: Form["status"];
	createdAt: string;
	updatedAt: string;
}

/**
 * Serialized form submission for API responses (dates as strings)
 */
export interface SerializedFormSubmission
	extends Omit<FormSubmission, "submittedAt"> {
	submittedAt: string;
}

/** Non-sensitive submission metadata returned by collection reads. */
export type SerializedFormSubmissionSummary = {
	id: string;
	formId: string;
	submittedAt: string;
	submittedBy?: string;
};

/**
 * Serialized form submission with parsed data
 */
export interface SerializedFormSubmissionWithData<
	TData = Record<string, unknown>,
> extends SerializedFormSubmission {
	/** Parsed data object (JSON.parse of data field). Null when the stored JSON is corrupted. */
	parsedData: TData | null;
	/** Joined form */
	form?: SerializedForm;
}

/**
 * Paginated list response for forms
 */
export interface PaginatedForms {
	items: SerializedForm[];
	total: number;
	limit: number;
	offset: number;
}

/** Minimal form context carried by the submission-read response. */
export interface SubmissionListFormContext {
	id: string;
	name: string;
	createdBy?: string;
}

/**
 * Paginated list response for form submissions
 */
export interface PaginatedFormSubmissions {
	/** Authoritative form facts returned by the submission-read operation. */
	form: SubmissionListFormContext | null;
	/** Metadata only. Fetch an individual submission to read its contents. */
	items: SerializedFormSubmissionSummary[];
	total: number;
	limit: number;
	offset: number;
}

// ============================================================================
// BACKEND HOOKS
// ============================================================================

/**
 * Context passed to all backend hooks
 */
export interface FormBuilderHookContext<TInput = unknown, TFacts = unknown> {
	/** Validated operation input. */
	readonly input: DeepReadonly<TInput>;
	/** Trusted facts derived by the backend before authorization. */
	readonly facts: DeepReadonly<TFacts>;
	/** Authorized request identity, or `null` for anonymous/trusted execution. */
	readonly identity: DeepReadonly<StackIdentity> | null;
	/** Request when invoked through HTTP or `forRequest()`. */
	readonly request?: Request;
	/** User ID if authenticated */
	readonly userId?: string;
	/** Request headers */
	readonly headers?: Headers;
	/** Client IP address (for rate limiting) */
	readonly ipAddress?: string;
	/** User agent string */
	readonly userAgent?: string;
}

/**
 * Context for submission-specific hooks
 */
export interface SubmissionHookContext<TInput = unknown, TFacts = unknown>
	extends FormBuilderHookContext<TInput, TFacts> {
	/** Form slug being submitted */
	readonly formSlug: string;
	/** Form ID */
	readonly formId: string;
}

type FormReadFacts = PermissionFactsFor<
	typeof formBuilderPermissions.form.read
>;
type FormRenderFacts = PermissionFactsFor<
	typeof formBuilderPermissions.form.render
>;
type FormCreateFacts = PermissionFactsFor<
	typeof formBuilderPermissions.form.create
>;
type FormUpdateFacts = PermissionFactsFor<
	typeof formBuilderPermissions.form.update
>;
type FormDeleteFacts = PermissionFactsFor<
	typeof formBuilderPermissions.form.delete
>;
type SubmissionCreateFacts = PermissionFactsFor<
	typeof formBuilderPermissions.submission.create
>;
type SubmissionReadFacts = PermissionFactsFor<
	typeof formBuilderPermissions.submission.read
>;
type SubmissionDeleteFacts = PermissionFactsFor<
	typeof formBuilderPermissions.submission.delete
>;

/** Authorized form-list lifecycle context. */
export type FormListOperationContext = FormBuilderHookContext<
	ListFormsQuery,
	FormReadFacts
>;
/** Authorized form-detail lifecycle context. */
export type FormGetOperationContext =
	| FormBuilderHookContext<{ id: string }, FormReadFacts>
	| FormBuilderHookContext<{ slug: string }, FormRenderFacts>;
/** Authorized editor-data lifecycle context. */
export type FormGetForUpdateOperationContext = FormBuilderHookContext<
	{ id: string },
	FormUpdateFacts
>;
/** Authorized form-create lifecycle context. */
export type FormCreateOperationContext = FormBuilderHookContext<
	CreateFormInput,
	FormCreateFacts
>;
/** Authorized form-update lifecycle context. */
export type FormUpdateOperationContext = FormBuilderHookContext<
	{ id: string; data: UpdateFormInput },
	FormUpdateFacts
>;
/** Authorized form-delete lifecycle context. */
export type FormDeleteOperationContext = FormBuilderHookContext<
	{ id: string },
	FormDeleteFacts
>;
/** Authorized public submission lifecycle context. */
export type SubmissionCreateOperationContext = SubmissionHookContext<
	{ slug: string } & SubmitFormInput,
	SubmissionCreateFacts
>;
/** Authorized submission-list lifecycle context. */
export type SubmissionListOperationContext = FormBuilderHookContext<
	{ formId: string; query: ListSubmissionsQuery },
	SubmissionReadFacts
>;
/** Authorized submission-detail lifecycle context. */
export type SubmissionGetOperationContext = FormBuilderHookContext<
	{ formId: string; submissionId: string },
	SubmissionReadFacts
>;
/** Authorized submission-delete lifecycle context. */
export type SubmissionDeleteOperationContext = FormBuilderHookContext<
	{ formId: string; submissionId: string },
	SubmissionDeleteFacts
>;

/** Typed context union used by the cross-operation error hook. */
export type FormBuilderOperationHookContext =
	| FormListOperationContext
	| FormGetOperationContext
	| FormGetForUpdateOperationContext
	| FormCreateOperationContext
	| FormUpdateOperationContext
	| FormDeleteOperationContext
	| SubmissionCreateOperationContext
	| SubmissionListOperationContext
	| SubmissionGetOperationContext
	| SubmissionDeleteOperationContext;

/**
 * Input data for creating a form
 */
export interface FormInput {
	name: string;
	slug: string;
	description?: string;
	schema: string;
	successMessage?: string;
	redirectUrl?: string;
	status?: "active" | "inactive" | "archived";
	createdBy?: string;
}

/**
 * Input data for updating a form
 */
export interface FormUpdate {
	name?: string;
	slug?: string;
	description?: string;
	schema?: string;
	successMessage?: string;
	redirectUrl?: string;
	status?: "active" | "inactive" | "archived";
}

/**
 * Backend hooks for Form Builder plugin
 *
 * Authorization runs before these hooks. Hooks receive trusted typed operation
 * context and can enforce domain invariants or perform lifecycle behavior.
 */
export interface FormBuilderBackendHooks {
	// ============================================================================
	// FORM CRUD HOOKS (Admin operations)
	// ============================================================================

	/** Called before listing forms to enforce domain preconditions. */
	onBeforeListForms?: (ctx: FormListOperationContext) => Promise<void> | void;

	/** Called before creating a form. Throw an error to deny, or return modified data. */
	onBeforeCreateForm?: (
		data: FormInput,
		ctx: FormCreateOperationContext,
	) => Promise<FormInput | void> | FormInput | void;

	/** Called after a form is created */
	onAfterCreateForm?: (
		form: SerializedForm,
		ctx: FormCreateOperationContext,
	) => Promise<void> | void;

	/** Called before getting a form by ID or slug. */
	onBeforeGetForm?: (
		idOrSlug: string,
		ctx: FormGetOperationContext,
	) => Promise<void> | void;

	/** Called before loading editor data through the form update permission. */
	onBeforeGetFormForUpdate?: (
		id: string,
		ctx: FormGetForUpdateOperationContext,
	) => Promise<void> | void;

	/** Called before updating a form. Throw an error to deny, or return modified data. */
	onBeforeUpdateForm?: (
		id: string,
		data: FormUpdate,
		ctx: FormUpdateOperationContext,
	) => Promise<FormUpdate | void> | FormUpdate | void;

	/** Called after a form is updated */
	onAfterUpdateForm?: (
		form: SerializedForm,
		ctx: FormUpdateOperationContext,
	) => Promise<void> | void;

	/** Called before deleting a form. Throw an error to deny. */
	onBeforeDeleteForm?: (
		id: string,
		ctx: FormDeleteOperationContext,
	) => Promise<void> | void;

	/** Called after a form is deleted */
	onAfterDeleteForm?: (
		id: string,
		ctx: FormDeleteOperationContext,
	) => Promise<void> | void;

	// ============================================================================
	// SUBMISSION HOOKS (Public form submissions)
	// ============================================================================

	/**
	 * Called before processing a form submission.
	 * Use for: spam protection, rate limiting, data validation/enrichment.
	 *
	 * Throw an error to reject submission (400), or return modified data to continue.
	 */
	onBeforeSubmission?: (
		formSlug: string,
		data: Record<string, unknown>,
		ctx: SubmissionCreateOperationContext,
	) => Promise<Record<string, unknown> | void> | Record<string, unknown> | void;

	/**
	 * Called after a submission is saved.
	 * Use for: sending emails, storing in CRM, triggering workflows.
	 */
	onAfterSubmission?: (
		submission: SerializedFormSubmission,
		form: SerializedForm,
		ctx: SubmissionCreateOperationContext,
	) => Promise<void> | void;

	/** Called when a submission fails */
	onErrorSubmission?: (
		error: Error,
		formSlug: string,
		data: Record<string, unknown>,
		ctx: SubmissionCreateOperationContext,
	) => Promise<void> | void;

	// ============================================================================
	// SUBMISSIONS MANAGEMENT HOOKS (Admin viewing submissions)
	// ============================================================================

	/** Called before listing submissions to enforce domain preconditions. */
	onBeforeListSubmissions?: (
		formId: string,
		ctx: SubmissionListOperationContext,
	) => Promise<void> | void;

	/** Called before getting a submission. Throw an error to deny access. */
	onBeforeGetSubmission?: (
		submissionId: string,
		ctx: SubmissionGetOperationContext,
	) => Promise<void> | void;

	/** Called before deleting a submission. Throw an error to deny. */
	onBeforeDeleteSubmission?: (
		submissionId: string,
		ctx: SubmissionDeleteOperationContext,
	) => Promise<void> | void;

	/** Called after a submission is deleted */
	onAfterDeleteSubmission?: (
		submissionId: string,
		ctx: SubmissionDeleteOperationContext,
	) => Promise<void> | void;

	// ============================================================================
	// ERROR HOOK
	// ============================================================================

	/** Called on any error */
	onError?: (
		error: Error,
		operation:
			| "list"
			| "get"
			| "create"
			| "update"
			| "delete"
			| "submit"
			| "listSubmissions"
			| "getSubmission"
			| "deleteSubmission",
		ctx: FormBuilderOperationHookContext,
	) => Promise<void> | void;
}

/**
 * Configuration for the Form Builder backend plugin
 */
export interface FormBuilderBackendConfig {
	/** Optional hooks for customizing behavior */
	hooks?: FormBuilderBackendHooks;
}

import { z } from "zod";

/**
 * Cap on the DB scan when free-text search forces the in-memory filter in
 * `getAllForms`, bounding server memory use.
 */
export const DEFAULT_MAX_PAGE_SIZE = 1000;

/**
 * Schema for listing forms with pagination and free-text search
 */
export const listFormsQuerySchema = z.object({
	status: z.enum(["active", "inactive", "archived"]).optional(),
	limit: z.coerce.number().min(1).max(100).optional().default(20),
	offset: z.coerce.number().min(0).optional().default(0),
	search: z.string().max(200).optional(),
});

/**
 * Schema for creating a form
 */
export const createFormSchema = z.object({
	name: z.string().min(1, "Name is required"),
	slug: z.string().min(1, "Slug is required"),
	description: z.string().optional(),
	schema: z.string().min(1, "Schema is required"),
	successMessage: z.string().optional(),
	redirectUrl: z.string().url().optional().or(z.literal("")),
	status: z
		.enum(["active", "inactive", "archived"])
		.optional()
		.default("active"),
});

/**
 * Schema for updating a form
 */
export const updateFormSchema = z.object({
	name: z.string().min(1, "Name is required").optional(),
	slug: z.string().min(1, "Slug is required").optional(),
	description: z.string().optional(),
	schema: z.string().min(1, "Schema is required").optional(),
	successMessage: z.string().optional(),
	redirectUrl: z.string().url().optional().or(z.literal("")),
	status: z.enum(["active", "inactive", "archived"]).optional(),
});

/**
 * Schema for form response
 */
export const formResponseSchema = z.object({
	id: z.string(),
	name: z.string(),
	slug: z.string(),
	description: z.string().nullable().optional(),
	schema: z.string(),
	successMessage: z.string().nullable().optional(),
	redirectUrl: z.string().nullable().optional(),
	status: z.string(),
	createdBy: z.string().nullable().optional(),
	createdAt: z.string(),
	updatedAt: z.string(),
});

/**
 * Schema for paginated forms response
 */
export const paginatedFormsResponseSchema = z.object({
	items: z.array(formResponseSchema),
	total: z.number(),
	limit: z.number(),
	offset: z.number(),
});

/**
 * Schema for listing form submissions with pagination
 */
export const listSubmissionsQuerySchema = z.object({
	limit: z.coerce.number().min(1).max(100).optional().default(20),
	offset: z.coerce.number().min(0).optional().default(0),
});

/**
 * Schema for submitting a form (public)
 */
export const submitFormSchema = z.object({
	// Use passthrough object for dynamic form data validation
	data: z.object({}).passthrough(),
});

/**
 * Schema for form submission response
 */
export const formSubmissionResponseSchema = z.object({
	id: z.string(),
	formId: z.string(),
	data: z.string(),
	submittedAt: z.string(),
	submittedBy: z.string().nullable().optional(),
	ipAddress: z.string().nullable().optional(),
	userAgent: z.string().nullable().optional(),
});

/**
 * Schema for form submission with parsed data response
 */
export const formSubmissionWithDataResponseSchema =
	formSubmissionResponseSchema.extend({
		// Use passthrough object for dynamic parsed data
		parsedData: z.object({}).passthrough(),
		form: formResponseSchema.optional(),
	});

/** Non-sensitive submission metadata returned by collection reads. */
export const formSubmissionSummaryResponseSchema = z.object({
	id: z.string(),
	formId: z.string(),
	submittedAt: z.string(),
	submittedBy: z.string().optional(),
});

/**
 * Schema for paginated submissions response
 */
export const paginatedSubmissionsResponseSchema = z.object({
	items: z.array(formSubmissionSummaryResponseSchema),
	total: z.number(),
	limit: z.number(),
	offset: z.number(),
});

// Export inferred types
export type ListFormsQuery = z.infer<typeof listFormsQuerySchema>;
export type CreateFormInput = z.infer<typeof createFormSchema>;
export type UpdateFormInput = z.infer<typeof updateFormSchema>;
export type ListSubmissionsQuery = z.infer<typeof listSubmissionsQuerySchema>;
export type SubmitFormInput = z.infer<typeof submitFormSchema>;

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";
import slug from "slug";

/**
 * Converts text to a URL-friendly slug
 */
export function slugify(text: string, locale: string = "en"): string {
	return slug(text, { lower: true, locale });
}

/**
 * Merges class names using clsx and tailwind-merge
 */
export function cn(...inputs: ClassValue[]) {
	return twMerge(clsx(inputs));
}

/**
 * Safely parses JSON with a fallback
 */
export function safeJsonParse<T>(json: string, fallback: T): T {
	try {
		return JSON.parse(json) as T;
	} catch {
		return fallback;
	}
}

/**
 * Extracts client IP address from request headers
 * Handles common proxy headers
 */
export function extractIpAddress(headers?: Headers): string | undefined {
	if (!headers) return undefined;

	// Check common proxy headers in order of preference
	const forwardedFor = headers.get("x-forwarded-for");
	if (forwardedFor) {
		// x-forwarded-for can contain multiple IPs, take the first one
		return forwardedFor.split(",")[0]?.trim();
	}

	const realIp = headers.get("x-real-ip");
	if (realIp) {
		return realIp.trim();
	}

	const cfConnectingIp = headers.get("cf-connecting-ip");
	if (cfConnectingIp) {
		return cfConnectingIp.trim();
	}

	return undefined;
}

/**
 * Extracts user agent from request headers
 */
export function extractUserAgent(headers?: Headers): string | undefined {
	if (!headers) return undefined;
	return headers.get("user-agent") || undefined;
}

import { definePermissions, permission } from "@btst/stack/authorization";
import { z } from "zod";

const formStatusSchema = z.enum(["active", "inactive", "archived"]);

const resolvedFormFacts = {
	formId: z.string(),
	ownerId: z.string().optional(),
	status: formStatusSchema,
};

/** Browser-safe, schema-backed permissions published by Form Builder. */
export const formBuilderPermissions = definePermissions("forms", {
	form: {
		/** Read the admin collection or one admin record. */
		read: permission(
			z.discriminatedUnion("scope", [
				z.object({ scope: z.literal("collection") }),
				z.object({
					scope: z.literal("record"),
					formId: z.string(),
					exists: z.boolean(),
					ownerId: z.string().optional(),
					status: formStatusSchema.optional(),
				}),
			]),
		),
		/** Render one public form resolved by slug. */
		render: permission(
			z.object({
				slug: z.string(),
				exists: z.boolean(),
				formId: z.string().optional(),
				ownerId: z.string().optional(),
				status: formStatusSchema.optional(),
			}),
		),
		/** Create a form. */
		create: permission(),
		/** Update a server-resolved form. */
		update: permission(
			z.object({
				...resolvedFormFacts,
			}),
		),
		/** Delete a server-resolved form and its submissions. */
		delete: permission(
			z.object({
				...resolvedFormFacts,
			}),
		),
	},
	submission: {
		/** Export all submission payloads for a server-resolved form. */
		export: permission(
			z.object({
				formId: z.string(),
				formExists: z.boolean(),
				ownerId: z.string().optional(),
			}),
		),
		/** Submit to a public, server-resolved form. */
		create: permission(
			z.object({
				slug: z.string(),
				exists: z.boolean(),
				formId: z.string().optional(),
				ownerId: z.string().optional(),
				status: formStatusSchema.optional(),
			}),
		),
		/** Read a form's collection or one server-resolved submission. */
		read: permission(
			z.discriminatedUnion("scope", [
				z.object({
					scope: z.literal("collection"),
					formId: z.string(),
					formExists: z.boolean(),
					ownerId: z.string().optional(),
				}),
				z.object({
					scope: z.literal("record"),
					formId: z.string(),
					submissionId: z.string(),
					exists: z.boolean(),
					ownerId: z.string().optional(),
					submittedBy: z.string().optional(),
				}),
			]),
		),
		/** Delete a server-resolved submission. */
		delete: permission(
			z.object({
				formId: z.string(),
				submissionId: z.string(),
				exists: z.boolean(),
				ownerId: z.string().optional(),
				submittedBy: z.string().optional(),
			}),
		),
	},
});

"use client";

import { useState, useMemo, type ComponentType } from "react";
import {
	PermissionAccess,
	usePluginOverrides,
	useTranslate,
} from "@btst/stack/context";
import { SteppedAutoForm } from "@/components/ui/auto-form/stepped-auto-form";
import { buildFieldConfigFromJsonSchema } from "@/components/ui/auto-form/helpers";
import { formSchemaToZod } from "@/lib/schema-converter";
import { Skeleton } from "@/components/ui/skeleton";
import { AlertCircle, CheckCircle } from "lucide-react";
import type { AutoFormInputComponentProps } from "@/components/ui/auto-form/types";

import { useFormBySlug, useSubmitForm } from "@btst/plugin-form-builder/client/hooks";
import type { FormBuilderPluginOverrides } from "../../overrides";
import type { SerializedFormSubmission } from "../../../types";
import { formBuilderPermissions } from "../../../permissions";
import { FORM_BUILDER_PLUGIN_ID } from "../../constants";
import { cn } from "../../../utils";

export interface FormRendererProps {
	/** Upload a standalone file and return its URL string. */
	onUpload?: (file: File) => Promise<string>;
	/** Form slug to render */
	slug: string;
	/** Callback when form submission succeeds */
	onSuccess?: (
		submission: SerializedFormSubmission & {
			form: { successMessage?: string; redirectUrl?: string };
		},
	) => void;
	/** Callback when form submission fails */
	onError?: (error: Error) => void;
	/** Custom field components (same as FormBuilder) */
	fieldComponents?: Record<string, ComponentType<AutoFormInputComponentProps>>;
	/** Override success message */
	successMessage?: React.ReactNode;
	/** Override submit button text */
	submitButtonText?: string;
	/** Custom loading component */
	LoadingComponent?: ComponentType;
	/** Custom error component */
	ErrorComponent?: ComponentType<{ error: Error }>;
	/** Class name for the form container */
	className?: string;
}

function DefaultLoadingComponent() {
	return (
		<div className="space-y-4">
			<Skeleton className="h-10 w-full" />
			<Skeleton className="h-10 w-full" />
			<Skeleton className="h-10 w-full" />
			<Skeleton className="h-10 w-32" />
		</div>
	);
}

function DefaultErrorComponent({ error }: { error: Error }) {
	const t = useTranslate();
	const { localization } = usePluginOverrides<FormBuilderPluginOverrides>(
		FORM_BUILDER_PLUGIN_ID,
	);

	return (
		<div className="flex flex-col items-center justify-center py-8 text-center">
			<div className="rounded-full bg-destructive/10 p-3 mb-4">
				<AlertCircle className="h-6 w-6 text-destructive" />
			</div>
			<h3 className="text-lg font-medium text-foreground mb-2">
				{localization?.FORM_BUILDER_RENDERER_LOAD_FAILED ??
					t("formBuilder.renderer.loadFailed", "Failed to load form")}
			</h3>
			<p className="text-sm text-muted-foreground max-w-sm">
				{error.message ||
					(localization?.FORM_BUILDER_RENDERER_UNEXPECTED_ERROR ??
						t(
							"formBuilder.renderer.unexpectedError",
							"An unexpected error occurred",
						))}
			</p>
		</div>
	);
}

function DefaultSuccessComponent({ message }: { message: React.ReactNode }) {
	const t = useTranslate();
	const { localization } = usePluginOverrides<FormBuilderPluginOverrides>(
		FORM_BUILDER_PLUGIN_ID,
	);

	return (
		<div className="flex flex-col items-center justify-center py-8 text-center">
			<div className="rounded-full bg-green-100 dark:bg-green-900 p-3 mb-4">
				<CheckCircle className="h-6 w-6 text-green-600 dark:text-green-400" />
			</div>
			<h3 className="text-lg font-medium text-foreground mb-2">
				{localization?.FORM_BUILDER_RENDERER_SUBMITTED_TITLE ??
					t("formBuilder.renderer.submittedTitle", "Form Submitted")}
			</h3>
			<p className="text-sm text-muted-foreground max-w-sm">{message}</p>
		</div>
	);
}

/**
 * FormRenderer component for rendering forms on the frontend.
 *
 * Uses SteppedAutoForm which automatically handles both single-step and multi-step forms.
 *
 * @example
 * ```tsx
 * <FormRenderer
 *   slug="contact-form"
 *   onSuccess={() => {
 *     toast.success("Thank you!");
 *   }}
 *   onError={(error) => {
 *     toast.error("Something went wrong");
 *   }}
 * />
 * ```
 */
export function FormRenderer({
	slug,
	onUpload: propOnUpload,
	onSuccess,
	onError,
	fieldComponents: propFieldComponents,
	successMessage: propSuccessMessage,
	submitButtonText,
	LoadingComponent = DefaultLoadingComponent,
	ErrorComponent = DefaultErrorComponent,
	className,
}: FormRendererProps) {
	const t = useTranslate();
	const {
		fieldComponents: overrideFieldComponents,
		onUpload: overrideOnUpload,
		localization,
		classNames,
	} = usePluginOverrides<FormBuilderPluginOverrides>(FORM_BUILDER_PLUGIN_ID);

	const formClassName = cn(className, classNames?.form);
	const { form, isLoading, error } = useFormBySlug(slug);
	const submitMutation = useSubmitForm(slug);

	const [submitted, setSubmitted] = useState(false);
	const [finalSuccessMessage, setFinalSuccessMessage] = useState<string | null>(
		null,
	);

	// Merge field components from props and overrides
	const mergedFieldComponents = useMemo(
		() => ({
			...overrideFieldComponents,
			...propFieldComponents,
		}),
		[overrideFieldComponents, propFieldComponents],
	);

	// Parse JSON Schema and create Zod schema
	const { zodSchema, fieldConfig } = useMemo(() => {
		if (!form?.schema) {
			return { zodSchema: null, fieldConfig: {} };
		}

		try {
			const parsedSchema = JSON.parse(form.schema);
			const zod = formSchemaToZod(parsedSchema);
			const config = buildFieldConfigFromJsonSchema(
				parsedSchema,
				mergedFieldComponents,
			);

			const applyUpload = (fields: Record<string, any>) => {
				for (const field of Object.values(fields)) {
					if (field.fieldType === "file")
						field.onUpload = propOnUpload ?? overrideOnUpload;
					for (const value of Object.values(field))
						if (value && typeof value === "object" && !Array.isArray(value))
							applyUpload({ child: value });
				}
			};
			applyUpload(config);
			return { zodSchema: zod, fieldConfig: config };
		} catch {
			return { zodSchema: null, fieldConfig: {} };
		}
	}, [form?.schema, mergedFieldComponents, propOnUpload, overrideOnUpload]);

	const handleSubmit = async (data: Record<string, unknown>) => {
		try {
			const result = await submitMutation.mutateAsync({ data });

			// Set success message
			const message =
				propSuccessMessage ||
				result.form.successMessage ||
				(localization?.FORM_BUILDER_RENDERER_THANK_YOU ??
					t("formBuilder.renderer.thankYou", "Thank you for your submission!"));
			setFinalSuccessMessage(message as string);
			setSubmitted(true);

			// Call onSuccess callback before any redirect
			onSuccess?.(result);

			// Handle redirect
			if (result.form.redirectUrl) {
				window.location.href = result.form.redirectUrl;
				return;
			}
		} catch (err) {
			onError?.(err as Error);
		}
	};

	// Loading state
	if (isLoading) {
		return (
			<div className={formClassName}>
				<LoadingComponent />
			</div>
		);
	}

	// Error state
	if (error) {
		return (
			<div className={formClassName}>
				<ErrorComponent error={error} />
			</div>
		);
	}

	// Form not found
	if (!form) {
		return (
			<div className={formClassName}>
				<ErrorComponent
					error={
						new Error(
							localization?.FORM_BUILDER_RENDERER_NOT_FOUND ??
								t("formBuilder.renderer.notFound", "Form not found"),
						)
					}
				/>
			</div>
		);
	}

	// Form not active
	if (form.status !== "active") {
		return (
			<div className={formClassName}>
				<ErrorComponent
					error={
						new Error(
							localization?.FORM_BUILDER_RENDERER_INACTIVE ??
								t(
									"formBuilder.renderer.inactive",
									"This form is not currently accepting submissions",
								),
						)
					}
				/>
			</div>
		);
	}

	// Schema parsing failed
	if (!zodSchema) {
		return (
			<div className={formClassName}>
				<ErrorComponent
					error={
						new Error(
							localization?.FORM_BUILDER_RENDERER_SCHEMA_ERROR ??
								t(
									"formBuilder.renderer.schemaError",
									"Failed to parse form schema",
								),
						)
					}
				/>
			</div>
		);
	}

	// Success state
	if (submitted && finalSuccessMessage) {
		return (
			<div className={formClassName}>
				<DefaultSuccessComponent message={finalSuccessMessage} />
			</div>
		);
	}

	// Render form using SteppedAutoForm
	// It automatically handles both single-step and multi-step forms
	return (
		<PermissionAccess
			permission={formBuilderPermissions.form.render({
				slug: form.slug,
				exists: true,
				formId: form.id,
				...(form.createdBy ? { ownerId: form.createdBy } : {}),
				status: form.status,
			})}
		>
			<PermissionAccess
				permission={formBuilderPermissions.submission.create({
					slug: form.slug,
					exists: true,
					formId: form.id,
					...(form.createdBy ? { ownerId: form.createdBy } : {}),
					status: form.status,
				})}
			>
				<div className={formClassName} data-testid="form-renderer">
					<SteppedAutoForm
						formSchema={zodSchema}
						fieldConfig={fieldConfig}
						onSubmit={(values) =>
							handleSubmit(values as Record<string, unknown>)
						}
						isSubmitting={submitMutation.isPending}
						submitButtonText={
							submitButtonText ||
							(localization?.FORM_BUILDER_BUTTON_SUBMIT ??
								t("formBuilder.common.buttonSubmit", "Submit"))
						}
					/>
				</div>
			</PermissionAccess>
		</PermissionAccess>
	);
}

