} from "lucide-react";

import { useForms, useSuspenseForms, useDeleteForm } from "@btst/plugin-form-builder/client/hooks";
import type { FormBuilderPluginOverrides } from "../../overrides";
import { PageWrapper } from "../shared/page-wrapper";
import { EmptyState } from "../shared/empty-state";
import { Pagination } from "../shared/pagination";
import { formBuilderPermissions } from "../../../permissions";
import { FORM_BUILDER_PLUGIN_ID } from "../../constants";
import { cn } from "../../../utils";

// URL-synced search state: `?q=...` while typing (history: replace), clean
// URL when the query is empty (the default is omitted from the URL).
const LIST_STATE_SCHEMA = {
	q: { type: "string", default: "", history: "replace" },
} as const satisfies ListStateSchema;

const SEARCH_DEBOUNCE_MS = 300;

export function FormListPage() {
	const t = useTranslate();
	const notify = useNotify();
	const { localization, classNames } =
		usePluginOverrides<FormBuilderPluginOverrides>(FORM_BUILDER_PLUGIN_ID);
	const { Link, navigate, resolve } = usePluginSiteNavigation(
		FORM_BUILDER_PLUGIN_ID,
	);

	const [{ q: search }, setListState] = useListState(
		"form-builder-forms",
		LIST_STATE_SCHEMA,
	);

	// Local input state debounced into the URL-synced query, so the list
	// query (and URL) only update after the user pauses typing.
	const [searchInput, setSearchInput] = useState(search);

	// External `q` changes (hydration after SSR-empty search params,
	// back/forward navigation) re-seed the input instead of being clobbered
	// by the debounced write below, which only reflects user edits.
	const lastSyncedSearch = useRef(search);
	useEffect(() => {
		if (search !== lastSyncedSearch.current) {
			lastSyncedSearch.current = search;
			setSearchInput(search);
		}
	}, [search]);

	useEffect(() => {
		if (searchInput === search) return;
		const timeout = setTimeout(() => {
			lastSyncedSearch.current = searchInput;
			setListState({ q: searchInput });
		}, SEARCH_DEBOUNCE_MS);
		return () => clearTimeout(timeout);
	}, [searchInput, search, setListState]);

	const hasSearch = search.trim().length > 0;

	// The default (unsearched) list stays on the suspense hook so SSR/SSG
	// hydration works; the searched list uses the non-suspense hook so
	// typing shows an inline loading state instead of suspending the page.
	const defaultList = useSuspenseForms();
	const searchedList = useForms({ search, enabled: hasSearch });

	const activeList = hasSearch ? searchedList : defaultList;
	const { forms, total, hasMore, isLoadingMore, loadMore } = activeList;
	const isSearchLoading = hasSearch && searchedList.isLoading;

	const deleteMutation = useDeleteForm();

	const [deleteId, setDeleteId] = useState<string | null>(null);

	const LinkComponent = Link || "a";

	const handleDelete = async () => {
		if (!deleteId) return;

		try {
			await deleteMutation.mutateAsync(deleteId);
		} catch {
			notify.error(
				localization?.FORM_BUILDER_TOAST_ERROR ??
					t("formBuilder.toasts.error", "An error occurred. Please try again."),
			);
			return;
		}
		notify.success(
			localization?.FORM_BUILDER_TOAST_DELETE_SUCCESS ??
				t("formBuilder.toasts.deleteSuccess", "Form deleted successfully"),
		);
		setDeleteId(null);
	};

	const getStatusBadge = (status: string) => {
		const colors: Record<string, string> = {
			active:
				"bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200",
			inactive:
				"bg-yellow-100 text-yellow-800 dark:bg-yellow-900 dark:text-yellow-200",
			archived: "bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-200",
		};
		return (
			<span
				className={`px-2 py-1 rounded-full text-xs font-medium ${colors[status] || colors.inactive}`}
			>
				{status}
			</span>
		);
	};

	const newFormButton = (
		<PermissionAccess permission={formBuilderPermissions.form.create()}>
			<Button asChild>
				<LinkComponent href={resolve("forms", "new").href}>
					<Plus className="mr-2 h-4 w-4" />
					{localization?.FORM_BUILDER_BUTTON_NEW_FORM ??
						t("formBuilder.common.buttonNewForm", "New Form")}
				</LinkComponent>
			</Button>
		</PermissionAccess>
	);

	return (
		<PageWrapper testId="form-list-page">
			<div className="w-full max-w-5xl space-y-6">
				<div className="flex items-center justify-between">
					<div>
						<h1 className="text-2xl font-bold">
							{localization?.FORM_BUILDER_LIST_TITLE ??
								t("formBuilder.list.title", "Forms")}
						</h1>
						<p className="text-muted-foreground">
							{localization?.FORM_BUILDER_LIST_SUBTITLE ??
								t("formBuilder.list.subtitle", "Manage your forms")}
						</p>
					</div>
					{newFormButton}
				</div>

				<div className="relative max-w-sm">
					<Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
					<Input
						data-testid="form-builder-list-search"
						value={searchInput}
						onChange={(e) => setSearchInput(e.target.value)}
						placeholder={
							localization?.FORM_BUILDER_LIST_SEARCH_PLACEHOLDER ??
							t("formBuilder.list.searchPlaceholder", "Search forms...")
						}
						className="pl-9"
					/>
					{isSearchLoading && (
						<Loader2 className="absolute right-3 top-1/2 h-4 w-4 -translate-y-1/2 animate-spin text-muted-foreground" />
					)}
				</div>

				{forms.length === 0 ? (
					isSearchLoading ? null : hasSearch ? (
						<EmptyState
							title={
								localization?.FORM_BUILDER_LIST_SEARCH_EMPTY ??
								t("formBuilder.list.searchEmpty", "No forms match your search")
							}
							description={
								localization?.FORM_BUILDER_LIST_SEARCH_EMPTY_DESCRIPTION ??
								t(
									"formBuilder.list.searchEmptyDescription",
									"Try a different search term.",
								)
							}
						/>
					) : (
						<EmptyState
							title={
								localization?.FORM_BUILDER_LIST_EMPTY ??
								t("formBuilder.list.empty", "No forms yet")
							}
							description={
								localization?.FORM_BUILDER_LIST_EMPTY_DESCRIPTION ??
								t(
									"formBuilder.list.emptyDescription",
									"Create your first form to get started.",
								)
							}
							action={newFormButton}
						/>
					)
				) : (
					<>
						<div
							className={cn("rounded-lg border", classNames?.table)}
							data-testid="form-builder-list-table"
						>
							<Table>
								<TableHeader>
									<TableRow>
										<TableHead>
											{localization?.FORM_BUILDER_LIST_COLUMN_NAME ??
												t("formBuilder.list.columnName", "Name")}
										</TableHead>
										<TableHead>
											{localization?.FORM_BUILDER_LIST_COLUMN_SLUG ??
												t("formBuilder.list.columnSlug", "Slug")}
										</TableHead>
										<TableHead>
											{localization?.FORM_BUILDER_LIST_COLUMN_STATUS ??
												t("formBuilder.list.columnStatus", "Status")}
										</TableHead>
										<TableHead>
											{localization?.FORM_BUILDER_LIST_COLUMN_CREATED ??
												t("formBuilder.list.columnCreated", "Created")}
										</TableHead>
										<TableHead className="w-12">
											{localization?.FORM_BUILDER_LIST_COLUMN_ACTIONS ??
												t("formBuilder.list.columnActions", "Actions")}
										</TableHead>
									</TableRow>
								</TableHeader>
								<TableBody>
									{forms.map((form) => (
										<TableRow key={form.id} className={classNames?.tableRow}>
											<TableCell className="font-medium">{form.name}</TableCell>
											<TableCell className="text-muted-foreground font-mono text-sm">
												{form.slug}
											</TableCell>
											<TableCell>{getStatusBadge(form.status)}</TableCell>
											<TableCell className="text-muted-foreground">
												{new Date(form.createdAt).toLocaleDateString()}
											</TableCell>
											<TableCell>
												<DropdownMenu>
													<DropdownMenuTrigger asChild>
														<Button variant="ghost" size="icon">
															<MoreHorizontal className="h-4 w-4" />
															<span className="sr-only">
																{localization?.FORM_BUILDER_LIST_COLUMN_ACTIONS ??
																	t(
																		"formBuilder.list.columnActions",
																		"Actions",
																	)}
															</span>
														</Button>
													</DropdownMenuTrigger>
													<DropdownMenuContent align="end">
														<PermissionAccess
															permission={formBuilderPermissions.form.update({
																formId: form.id,
																...(form.createdBy
																	? { ownerId: form.createdBy }
																	: {}),
																status: form.status,
															})}
														>
															<DropdownMenuItem
																onClick={() =>
																	navigate("forms", form.id, "edit")
																}
															>
																<Pencil className="mr-2 h-4 w-4" />
																{localization?.FORM_BUILDER_LIST_ACTION_EDIT ??
																	t("formBuilder.list.actionEdit", "Edit")}
															</DropdownMenuItem>
														</PermissionAccess>
														<PermissionAccess
															permission={formBuilderPermissions.submission.read(
																{
																	scope: "collection",
																	formId: form.id,
																	formExists: true,
																	...(form.createdBy
																		? { ownerId: form.createdBy }
																		: {}),
																},
															)}
														>
															<DropdownMenuItem
																onClick={() =>
																	navigate("forms", form.id, "submissions")
																}
															>
																<FileText className="mr-2 h-4 w-4" />
																{localization?.FORM_BUILDER_LIST_ACTION_SUBMISSIONS ??
																	t(
																		"formBuilder.list.actionSubmissions",
																		"Submissions",
																	)}
															</DropdownMenuItem>
														</PermissionAccess>
														<PermissionAccess
															permission={formBuilderPermissions.form.delete({
																formId: form.id,
																...(form.createdBy
																	? { ownerId: form.createdBy }
																	: {}),
																status: form.status,
															})}
														>
															<DropdownMenuItem
																className="text-destructive"
																onClick={() => setDeleteId(form.id)}
															>
																<Trash2 className="mr-2 h-4 w-4" />
																{localization?.FORM_BUILDER_LIST_ACTION_DELETE ??
																	t("formBuilder.list.actionDelete", "Delete")}
															</DropdownMenuItem>
														</PermissionAccess>
													</DropdownMenuContent>
												</DropdownMenu>
											</TableCell>
										</TableRow>
									))}
								</TableBody>
							</Table>
						</div>

						<Pagination
							total={total}
							showing={forms.length}
							hasMore={hasMore}
							isLoadingMore={isLoadingMore}
							onLoadMore={loadMore}
							className={classNames?.pagination}
							labels={{
								showing:
									localization?.FORM_BUILDER_LIST_PAGINATION_SHOWING ??
									t(
										"formBuilder.list.paginationShowing",
										"Showing {count} of {total}",
									),
								next:
									localization?.FORM_BUILDER_LIST_PAGINATION_NEXT ??
									t("formBuilder.list.paginationNext", "Load More"),
								loading:
									localization?.FORM_BUILDER_STATUS_LOADING ??
									t("formBuilder.common.statusLoading", "Loading..."),
							}}
						/>
					</>
				)}
			</div>

			{/* Delete confirmation dialog */}
			<AlertDialog open={!!deleteId} onOpenChange={() => setDeleteId(null)}>
				<AlertDialogContent>
					<AlertDialogHeader>
						<AlertDialogTitle>
							{localization?.FORM_BUILDER_LIST_DELETE_TITLE ??
								t("formBuilder.list.deleteTitle", "Delete Form")}
						</AlertDialogTitle>
						<AlertDialogDescription>
							{localization?.FORM_BUILDER_EDITOR_DELETE_CONFIRM ??
								t(
									"formBuilder.editor.deleteConfirm",
									"Are you sure you want to delete this form? All submissions will also be deleted.",
								)}
						</AlertDialogDescription>
					</AlertDialogHeader>
					<AlertDialogFooter>
						<AlertDialogCancel>
							{localization?.FORM_BUILDER_BUTTON_CANCEL ??
								t("formBuilder.common.buttonCancel", "Cancel")}
						</AlertDialogCancel>
						<AlertDialogAction
							onClick={handleDelete}
							className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
						>
							{deleteMutation.isPending
								? (localization?.FORM_BUILDER_STATUS_DELETING ??
									t("formBuilder.common.statusDeleting", "Deleting..."))
								: (localization?.FORM_BUILDER_BUTTON_DELETE ??
									t("formBuilder.common.buttonDelete", "Delete"))}
						</AlertDialogAction>
					</AlertDialogFooter>
				</AlertDialogContent>
			</AlertDialog>
		</PageWrapper>
	);
}

"use client";

import { lazy } from "react";
import { usePluginOverrides } from "@btst/stack/context";
import type { FormBuilderPluginOverrides } from "../../overrides";
import { ComposedRoute } from "@btst/stack/client/components";
import { DefaultError } from "../shared/default-error";
import { FormListSkeleton } from "../loading/form-list-skeleton";
import { NotFoundPage } from "./404-page";
import { formBuilderPermissions } from "../../../permissions";
import { FORM_BUILDER_PLUGIN_ID } from "../../constants";

const FormListPage = lazy(() =>
	import("./form-list-page.internal").then((m) => ({
		default: m.FormListPage,
	})),
);

export function FormListPageComponent() {
	const { onRouteError } = usePluginOverrides<FormBuilderPluginOverrides>(
		FORM_BUILDER_PLUGIN_ID,
	);

	return (
		<ComposedRoute
			path="/forms"
			permission={formBuilderPermissions.form.read({ scope: "collection" })}
			PageComponent={FormListPage}
			ErrorComponent={DefaultError}
			LoadingComponent={FormListSkeleton}
			NotFoundComponent={NotFoundPage}
			onError={(error) => {
				if (onRouteError) {
					onRouteError("formList", error, {
						path: "/forms",
						isSSR: typeof window === "undefined",
					});
				}
			}}
		/>
	);
}

"use client";

import { useEffect, useState } from "react";
import {
	useNotify,
	PermissionAccess,
	usePluginOverrides,
	usePluginSiteNavigation,
	useTranslate,
	useIdentity,
} from "@btst/stack/context";
import { Button } from "@/components/ui/button";
import {
	Table,
	TableBody,
	TableCell,
	TableHead,
	TableHeader,
	TableRow,
} from "@/components/ui/table";
import {
	AlertDialog,
	AlertDialogAction,
	AlertDialogCancel,
	AlertDialogContent,
	AlertDialogDescription,
	AlertDialogFooter,
	AlertDialogHeader,
	AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import {
	Dialog,
	DialogContent,
	DialogDescription,
	DialogHeader,
	DialogTitle,
} from "@/components/ui/dialog";
import { ArrowLeft, Trash2, Eye } from "lucide-react";

import {
	useSuspenseSubmissions,
	useSubmission,
	useDeleteSubmission,
	useExportSubmissions,
} from "@btst/plugin-form-builder/client/hooks";
import type { FormBuilderPluginOverrides } from "../../overrides";
import { PageWrapper } from "../shared/page-wrapper";
import { EmptyState } from "../shared/empty-state";
import { Pagination } from "../shared/pagination";
import { formBuilderPermissions } from "../../../permissions";
import { FORM_BUILDER_PLUGIN_ID } from "../../constants";
import { cn } from "../../../utils";

export interface SubmissionsPageProps {
	formId: string;
}

export function SubmissionsPage({ formId }: SubmissionsPageProps) {
	const t = useTranslate();
	const notify = useNotify();
	const { localization, classNames } =
		usePluginOverrides<FormBuilderPluginOverrides>(FORM_BUILDER_PLUGIN_ID);
	const { identity } = useIdentity();
	const { Link: LinkComponent, resolve } = usePluginSiteNavigation(
		FORM_BUILDER_PLUGIN_ID,
	);

	const { form, submissions, total, hasMore, isLoadingMore, loadMore } =
		useSuspenseSubmissions(formId);
	const exportMutation = useExportSubmissions();
	const deleteMutation = useDeleteSubmission(formId);

	const [deleteId, setDeleteId] = useState<string | null>(null);
	const [viewSubmissionId, setViewSubmissionId] = useState<string | null>(null);
	const {
		submission: viewSubmission,
		isLoading: isViewLoading,
		error: viewError,
	} = useSubmission(formId, viewSubmissionId ?? undefined);

	// A detail response was authorized for the identity that opened it. Close
	// the dialog immediately when that identity snapshot changes; the hook also
	// partitions its sensitive cache by identity before any subsequent fetch.
	useEffect(() => {
		setViewSubmissionId(null);
	}, [identity]);

	const handleDelete = async () => {
		if (!deleteId) return;

		try {
			await deleteMutation.mutateAsync(deleteId);
		} catch {
			notify.error(
				localization?.FORM_BUILDER_TOAST_ERROR ??
					t("formBuilder.toasts.error", "An error occurred. Please try again."),
			);
			return;
		}
		notify.success(
			localization?.FORM_BUILDER_TOAST_SUBMISSION_DELETED ??
				t(
					"formBuilder.toasts.submissionDeleted",
					"Submission deleted successfully",
				),
		);
		setDeleteId(null);
	};

	return (
		<PageWrapper testId="submissions-page">
			<div className="w-full max-w-5xl space-y-6">
				<div className="flex items-center gap-4">
					<Button variant="ghost" size="icon" asChild>
						<LinkComponent href={resolve("forms").href}>
							<ArrowLeft className="h-4 w-4" />
						</LinkComponent>
					</Button>
					<div>
						<h1 className="text-2xl font-bold">
							{form?.name ||
								(localization?.FORM_BUILDER_SUBMISSIONS_TITLE ??
									t("formBuilder.submissions.title", "Submissions"))}
						</h1>
						<p className="text-muted-foreground">
							{localization?.FORM_BUILDER_SUBMISSIONS_SUBTITLE ??
								t("formBuilder.submissions.subtitle", "View form submissions")}
						</p>
					</div>
				</div>

				<PermissionAccess
					permission={formBuilderPermissions.submission.export({
						formId,
						formExists: true,
						...(form?.createdBy ? { ownerId: form.createdBy } : {}),
					})}
				>
					<Button
						variant="outline"
						disabled={exportMutation.isPending}
						onClick={async () => {
							try {
								const { csv, filename } =
									await exportMutation.mutateAsync(formId);
								const url = URL.createObjectURL(
									new Blob(["\uFEFF", csv], { type: "text/csv;charset=utf-8" }),
								);
								const anchor = document.createElement("a");
								anchor.href = url;
								anchor.download = filename;
								anchor.click();
								setTimeout(() => URL.revokeObjectURL(url), 1000);
							} catch {
								notify.error(
									t(
										"formBuilder.submissions.exportFailed",
										"Export failed. Please try again.",
									),
								);
							}
						}}
					>
						{exportMutation.isPending
							? t("formBuilder.submissions.exporting", "Exporting…")
							: t("formBuilder.submissions.exportCsv", "Export CSV")}
					</Button>
				</PermissionAccess>

				{submissions.length === 0 ? (
					<EmptyState
						title={
							localization?.FORM_BUILDER_SUBMISSIONS_EMPTY ??
							t("formBuilder.submissions.empty", "No submissions yet")
						}
						description={
							localization?.FORM_BUILDER_SUBMISSIONS_EMPTY_DESCRIPTION ??
							t(
								"formBuilder.submissions.emptyDescription",
								"Submissions will appear here when users submit this form.",
							)
						}
					/>
				) : (
					<>
						<div
							className={cn("rounded-lg border", classNames?.table)}
							data-testid="form-builder-submissions-table"
						>
							<Table>
								<TableHeader>
									<TableRow>
										<TableHead className="w-24">
											{localization?.FORM_BUILDER_SUBMISSIONS_COLUMN_ID ??
												t("formBuilder.submissions.columnId", "ID")}
										</TableHead>
										<TableHead>
											{localization?.FORM_BUILDER_SUBMISSIONS_COLUMN_SUBMITTED_AT ??
												t(
													"formBuilder.submissions.columnSubmittedAt",
													"Submitted",
												)}
										</TableHead>
										<TableHead className="w-24">
											{localization?.FORM_BUILDER_SUBMISSIONS_COLUMN_ACTIONS ??
												t("formBuilder.submissions.columnActions", "Actions")}
										</TableHead>
									</TableRow>
								</TableHeader>
								<TableBody>
									{submissions.map((sub) => (
										<TableRow key={sub.id} className={classNames?.tableRow}>
											<TableCell className="font-mono text-xs">
												{sub.id.slice(0, 8)}...
											</TableCell>
											<TableCell className="text-muted-foreground">
												{new Date(sub.submittedAt).toLocaleString()}
											</TableCell>
											<TableCell>
												<div className="flex gap-1">
													<PermissionAccess
														permission={formBuilderPermissions.submission.read({
															scope: "record",
															formId,
															submissionId: sub.id,
															exists: true,
															...(form?.createdBy
																? { ownerId: form.createdBy }
																: {}),
															...(sub.submittedBy
																? { submittedBy: sub.submittedBy }
																: {}),
														})}
													>
														<Button
															variant="ghost"
															size="icon"
															onClick={() => setViewSubmissionId(sub.id)}
														>
															<Eye className="h-4 w-4" />
															<span className="sr-only">
																{localization?.FORM_BUILDER_SUBMISSIONS_ACTION_VIEW ??
																	t(
																		"formBuilder.submissions.actionView",
																		"View",
																	)}
															</span>
														</Button>
													</PermissionAccess>
													<PermissionAccess
														permission={formBuilderPermissions.submission.delete(
															{
																formId,
																submissionId: sub.id,
																exists: true,
																...(form?.createdBy
																	? { ownerId: form.createdBy }
																	: {}),
																...(sub.submittedBy
																	? { submittedBy: sub.submittedBy }
																	: {}),
															},
														)}
													>
														<Button
															variant="ghost"
															size="icon"
															className="text-destructive"
															onClick={() => setDeleteId(sub.id)}
														>
															<Trash2 className="h-4 w-4" />
															<span className="sr-only">
																{localization?.FORM_BUILDER_SUBMISSIONS_ACTION_DELETE ??
																	t(
																		"formBuilder.submissions.actionDelete",
																		"Delete",
																	)}
															</span>
														</Button>
													</PermissionAccess>
												</div>
											</TableCell>
										</TableRow>
									))}
								</TableBody>
							</Table>
						</div>

						<Pagination
							total={total}
							showing={submissions.length}
							hasMore={hasMore}
							isLoadingMore={isLoadingMore}
							onLoadMore={loadMore}
							className={classNames?.pagination}
							labels={{
								showing:
									localization?.FORM_BUILDER_LIST_PAGINATION_SHOWING ??
