// UTILITY FUNCTIONS
// ============================================================================

/**
 * Check if a JSON Schema has multi-step configuration.
 */
export function hasSteps(jsonSchema: FormJsonSchema): boolean {
  return Array.isArray(jsonSchema.steps) && jsonSchema.steps.length > 0;
}

/**
 * Get steps from a JSON Schema.
 */
export function getSteps(jsonSchema: FormJsonSchema): FormStep[] {
  return jsonSchema.steps ?? [];
}

/**
 * Get the step group map from a JSON Schema.
 * Returns a map of field names to step indices.
 */
export function getStepGroupMap(jsonSchema: FormJsonSchema): Record<string, number> {
  return jsonSchema.stepGroupMap ?? extractStepGroupMap(jsonSchema);
}

/** A single visibility condition against a sibling field's value. */
export type ShowIfCondition = {
  field: string;
  operator: "equals" | "notEquals" | "in" | "isTruthy";
  value?: unknown;
};

/** Evaluate a form visibility rule without coercing the comparison value. */
export function matchesShowIf(condition: ShowIfCondition | undefined, values: Record<string, unknown>): boolean {
  if (!condition) return true;
  const value = Object.hasOwn(values, condition.field) ? values[condition.field] : undefined;
  switch (condition.operator) {
    case "equals": return value === condition.value;
    case "notEquals": return value !== condition.value;
    case "in": return Array.isArray(condition.value) && condition.value.includes(value);
    case "isTruthy": return Boolean(value);
    default: return false;
  }
}

import type {
  FormBuilderComponentDefinition,
  FormBuilderField,
  FormStep,
  JSONSchema,
  JSONSchemaProperty,
} from "./types";
import { beautifyObjectName } from "../auto-form/helpers";

/**
 * Helper to convert fields to JSON Schema properties (recursive)
 * @param includeStepGroup - Whether to include stepGroup in the schema (only for multi-step forms)
 */
function fieldsToProperties(
  fields: FormBuilderField[],
  components: FormBuilderComponentDefinition[],
  includeStepGroup: boolean = false
): Record<string, JSONSchemaProperty> {
  const properties: Record<string, JSONSchemaProperty> = {};

  for (const field of fields) {
    const component = components.find((c) => c.type === field.type);
    if (!component) {
      console.warn(`Unknown component type: ${field.type}`);
      continue;
    }

    const isRequired = field.props.required ?? false;
    const schemaProp = component.toJSONSchema(field.props, isRequired);
    if (field.props.showIf) schemaProp.showIf = field.props.showIf;

    // Add stepGroup if we're in multi-step mode and field has a stepGroup
    if (includeStepGroup && field.stepGroup !== undefined) {
      schemaProp.stepGroup = field.stepGroup;
    }

    // Handle nested object fields
    if (field.type === "object" && field.children && field.children.length > 0) {
      schemaProp.properties = fieldsToProperties(field.children, components, false);
      const childRequired = field.children
        .filter((child) => child.props.required)
        .map((child) => child.id);
      if (childRequired.length > 0) {
        schemaProp.required = childRequired;
      }
    }

    // Handle nested array fields
    if (field.type === "array" && field.itemTemplate && field.itemTemplate.length > 0) {
      schemaProp.items = {
        type: "object",
        properties: fieldsToProperties(field.itemTemplate, components, false),
      };
      const itemRequired = field.itemTemplate
        .filter((item) => item.props.required)
        .map((item) => item.id);
      if (itemRequired.length > 0) {
        schemaProp.items.required = itemRequired;
      }
    }

    properties[field.id] = schemaProp;
  }

  return properties;
}

/**
 * Helper to get required field IDs from a list of fields
 */
function getRequiredFieldIds(fields: FormBuilderField[]): string[] {
  return fields.filter((f) => f.props.required).map((f) => f.id);
}

/**
 * Convert internal fields to JSON Schema
 * @param steps - Optional steps array for multi-step forms
 */
export function fieldsToJSONSchema(
  fields: FormBuilderField[],
  components: FormBuilderComponentDefinition[],
  steps?: FormStep[]
): JSONSchema {
  // Include stepGroup in properties only if we have multiple steps
  const hasMultipleSteps = steps && steps.length > 1;
  const properties = fieldsToProperties(fields, components, hasMultipleSteps);
  const required = getRequiredFieldIds(fields);

  return {
    type: "object",
    properties,
    ...(required.length > 0 ? { required } : {}),
    // Only include steps if there are multiple steps
    ...(hasMultipleSteps ? { steps } : {}),
  };
}

/**
 * Helper to parse JSON Schema properties into fields (recursive).
 *
 * Step assignment is read from two possible sources, in order:
 *  1. `prop.stepGroup` on the property itself (the format the visual
 *     FormBuilder writes on save).
 *  2. `stepGroupMap[fieldName]` at the schema root (the format produced by
 *     `zodToFormSchema(schema, { steps, stepGroupMap })` — see
 *     `packages/ui/src/lib/schema-converter.ts`).
 *
 * Without (2), Zod-seeded multi-step forms render every field on step 0 in the
 * admin canvas — the other step tabs look empty even though the runtime
 * `<FormRenderer>` / `SteppedAutoForm` show all fields correctly.
 */
function propertiesToFields(
  properties: Record<string, JSONSchemaProperty>,
  requiredSet: Set<string>,
  components: FormBuilderComponentDefinition[],
  stepGroupMap?: Record<string, number>
): FormBuilderField[] {
  const fields: FormBuilderField[] = [];

  for (const [key, prop] of Object.entries(properties)) {
    const isRequired = requiredSet.has(key);
    let field: FormBuilderField | null = null;

    // Try each component's fromJSONSchema in order
    // Components are ordered by specificity (more specific first)
    for (const component of components) {
      field = component.fromJSONSchema(prop, key, isRequired);
      if (field) {
        break;
      }
    }

    // Resolve step assignment: per-property `stepGroup` wins, then fall back
    // to the root-level `stepGroupMap` so Zod-converted schemas work.
    const resolvedStepGroup =
      prop.stepGroup !== undefined ? prop.stepGroup : stepGroupMap?.[key];

    if (field) {
      if (prop.showIf) field.props.showIf = prop.showIf;
      if (resolvedStepGroup !== undefined) {
        field.stepGroup = resolvedStepGroup;
      }

      // Handle nested object fields
      if (field.type === "object" && prop.properties) {
        const childRequiredSet = new Set(prop.required || []);
        field.children = propertiesToFields(prop.properties, childRequiredSet, components);
      }

      // Handle nested array fields
      if (field.type === "array" && prop.items?.properties) {
        const itemRequiredSet = new Set(prop.items.required || []);
        field.itemTemplate = propertiesToFields(prop.items.properties, itemRequiredSet, components);
      }

      fields.push(field);
    } else {
      // Fallback: create a generic text field for unknown types.
      // Label resolution mirrors `getLabel` in `./components/index.tsx` so the
      // admin canvas always shows a humanised label for unknown shapes too.
      console.warn(`Could not parse JSON Schema property: ${key}`, prop);
      fields.push({
        id: key,
        type: "text",
        props: {
          label: prop.label || prop.title || beautifyObjectName(key),
          description: prop.description,
          placeholder: prop.placeholder,
          required: isRequired,
        },
        // Include stepGroup even for fallback fields
        ...(resolvedStepGroup !== undefined ? { stepGroup: resolvedStepGroup } : {}),
      });
    }
  }

  return fields;
}

/**
 * Result of parsing a JSON Schema
 */
export interface ParsedSchema {
  fields: FormBuilderField[];
  steps: FormStep[];
}

/**
 * Convert JSON Schema to internal fields and extract steps.
 *
 * Accepts both flavours of multi-step encoding:
 *  - Per-property `stepGroup` (FormBuilder's canonical save format)
 *  - Root-level `stepGroupMap` (what `zodToFormSchema()` produces)
 *
 * The visual builder always normalises to per-property `stepGroup` on save.
 */
export function jsonSchemaToFieldsAndSteps(
  schema: JSONSchema | null | undefined,
  components: FormBuilderComponentDefinition[]
): ParsedSchema {
  if (!schema || !schema.properties) {
    return { fields: [], steps: [] };
  }

  const requiredSet = new Set(schema.required || []);
  const fields = propertiesToFields(
    schema.properties,
    requiredSet,
    components,
    schema.stepGroupMap
  );
  const steps = schema.steps || [];

  return { fields, steps };
}

/**
 * Convert JSON Schema to internal fields
 * @deprecated Use jsonSchemaToFieldsAndSteps for multi-step support
 */
export function jsonSchemaToFields(
  schema: JSONSchema | null | undefined,
  components: FormBuilderComponentDefinition[]
): FormBuilderField[] {
  return jsonSchemaToFieldsAndSteps(schema, components).fields;
}

/**
 * Generate a unique field ID
 */
export function generateFieldId(prefix: string = "field"): string {
  return `${prefix}_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
}

/**
 * Sanitize a field ID to be a valid JSON Schema property key
 */
export function sanitizeFieldId(id: string): string {
  return id.replace(/[^a-zA-Z0-9_]/g, "_").replace(/^[0-9]/, "_$&");
}

/**
 * Generate a unique step ID
 */
export function generateStepId(): string {
  return `step_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
}

/**
 * Create a new step with default title
 */
export function createStep(index: number): FormStep {
  return {
    id: generateStepId(),
    title: `Step ${index + 1}`,
  };
}

import { z } from "zod";

/**
 * Validation Schemas Registry
 *
 * This file defines type-safe validation schemas for the form-builder properties editor.
 * Based on the Zod serialization analysis, only serializable properties are included.
 *
 * Usage:
 *   propertiesSchema: baseMetaSchema
 *     .merge(VALIDATION_SCHEMAS[backingType])
 *     .merge(z.object({ defaultValue: DEFAULT_VALUE_SCHEMAS[backingType] }))
 */

// ============================================================================
// BASE META SCHEMAS
// ============================================================================

/**
 * Base meta properties (universal - all field types)
 * Includes: label, description, required
 */
export const baseMetaSchema = z.object({
  label: z.string().min(1).meta({ label: "Label" }),
  description: z.string().optional().meta({ label: "Description" }),
  required: z
    .boolean()
    .default(false)
    .meta({ label: "Required", fieldType: "switch" }),
});

/**
 * Extended base with placeholder (for text-like fields only)
 * Use for: text, email, password, url, phone, textarea, number, select
 */
export const baseMetaSchemaWithPlaceholder = baseMetaSchema.merge(
  z.object({
    placeholder: z.string().optional().meta({ label: "Placeholder" }),
  })
);

// ============================================================================
// DEFAULT VALUE SCHEMAS
// ============================================================================

/**
 * Default value schemas - typed per backing Zod type
 * Serializes to JSON Schema as { "default": value }
 */
export const DEFAULT_VALUE_SCHEMAS = {
  string: z.string().optional().meta({ label: "Default Value" }),
  number: z.number().optional().meta({ label: "Default Value" }),
  boolean: z
    .boolean()
    .default(false)
    .meta({ label: "Default Value", fieldType: "switch" }),
  date: z.date().optional().meta({ label: "Default Date", fieldType: "date" }),
  enum: z
    .string()
    .optional()
    .meta({
      label: "Default Value",
      description: "Must match one of the options",
    }),
} as const;

// ============================================================================
// TYPE-SPECIFIC VALIDATION SCHEMAS
// ============================================================================

/**
 * String validation schema
 * Serializes to: minLength, maxLength, pattern
 */
export const stringValidationSchema = z.object({
  minLength: z
    .number()
    .int()
    .min(0)
    .optional()
    .meta({ label: "Min Length" }),
  maxLength: z
    .number()
    .int()
    .min(1)
    .optional()
    .meta({ label: "Max Length" }),
  // Note: pattern/regex is serializable but requires careful UX for input
  // Uncomment to enable:
  // pattern: z.string().optional().meta({ label: "Pattern (Regex)" }),
});

/**
 * Number validation schema
 * Serializes to: minimum, maximum, multipleOf
 */
export const numberValidationSchema = z.object({
  min: z.number().optional().meta({ label: "Minimum" }),
  max: z.number().optional().meta({ label: "Maximum" }),
  // Note: multipleOf is serializable but less commonly used
  // Uncomment to enable:
  // multipleOf: z.number().optional().meta({ label: "Multiple Of" }),
});

/**
 * Boolean validation schema
 * No additional validation constraints - booleans are just true/false
 */
export const booleanValidationSchema = z.object({});

/**
 * Date validation schema
 * Serializes to: formatMinimum, formatMaximum (with date-time override)
 * Note: Currently date min/max requires custom handling in toJSONSchema
 */
export const dateValidationSchema = z.object({
  // Date min/max can be added when the date serialization is refined
  // minDate: z.date().optional().meta({ label: "Minimum Date", fieldType: "date" }),
  // maxDate: z.date().optional().meta({ label: "Maximum Date", fieldType: "date" }),
});

/**
 * Enum options schema (for select and radio)
 * The options textarea - user enters one option per line
 */
export const enumOptionsSchema = z.object({
  options: z.string().meta({
    label: "Options (one per line)",
    fieldType: "textarea",
    description: "Enter each option on a new line",
  }),
});

/**
 * Object validation schema
 * Object fields don't have their own validation - validation comes from children
 */
export const objectValidationSchema = z.object({});

/**
 * Array validation schema
 * Serializes to: minItems, maxItems
 */
export const arrayValidationSchema = z.object({
  minItems: z
    .number()
    .int()
    .min(0)
    .optional()
    .meta({ label: "Min Items" }),
  maxItems: z
    .number()
    .int()
    .min(1)
    .optional()
    .meta({ label: "Max Items" }),
});

// ============================================================================
// VALIDATION SCHEMAS REGISTRY
// ============================================================================

/**
 * Registry mapping backing Zod type to validation schema
 * Only includes properties confirmed serializable by the analysis script
 */
export const VALIDATION_SCHEMAS = {
  string: stringValidationSchema,
  number: numberValidationSchema,
  boolean: booleanValidationSchema,
  date: dateValidationSchema,
  enum: enumOptionsSchema,
  object: objectValidationSchema,
  array: arrayValidationSchema,
} as const;

// ============================================================================
// HELPER FUNCTIONS
// ============================================================================

// Note: The composePropertiesSchema helper was removed due to complex TypeScript 
// inference issues with Zod's merge types. Instead, compose schemas directly:
//
// Example usage:
//   baseMetaSchemaWithPlaceholder
//     .merge(stringValidationSchema)
//     .merge(z.object({ defaultValue: DEFAULT_VALUE_SCHEMAS.string }))

// ============================================================================
// TYPE EXPORTS
// ============================================================================

export type BackingZodType = keyof typeof VALIDATION_SCHEMAS;
export type BaseMetaSchemaType = z.infer<typeof baseMetaSchema>;
export type BaseMetaSchemaWithPlaceholderType = z.infer<
  typeof baseMetaSchemaWithPlaceholder
>;

"use client";

import { useMemo } from "react";
import { useDroppable } from "@dnd-kit/core";
import {
  SortableContext,
  verticalListSortingStrategy,
} from "@dnd-kit/sortable";
import { cn } from "@/lib/utils";
import { SortableField } from "./sortable-field";
import { ConditionEditor } from "./condition-editor";
import { StepTabs } from "./step-tabs";
import type { FormBuilderField, FormBuilderComponentDefinition, FormStep } from "./types";

interface DropZoneProps {
  id: string;
  isDraggingFromPalette: boolean;
}

function DropZone({ id, isDraggingFromPalette }: DropZoneProps) {
  const { setNodeRef, isOver } = useDroppable({
    id,
  });

  if (!isDraggingFromPalette) {
    return null;
  }

  return (
    <div
      ref={setNodeRef}
      className={cn(
        "h-2 rounded-full transition-all duration-200",
        isOver
          ? "h-3 bg-primary animate-pulse"
          : "bg-muted-foreground/20"
      )}
    />
  );
}

interface CanvasProps {
  fields: FormBuilderField[];
  components: FormBuilderComponentDefinition[];
  onEditField: (id: string) => void;
  onDeleteField: (id: string) => void;
  /** Callback to configure nested fields for object/array types */
  onConfigureNested?: (id: string) => void;
  isDraggingFromPalette: boolean;
  className?: string;
  /** Steps for multi-step forms */
  steps: FormStep[];
  /** Currently active step index */
  activeStepIndex: number;
  /** Callback when active step changes */
  onActiveStepChange: (index: number) => void;
  /** Callback to add a new step */
  onAddStep: () => void;
  /** Callback to delete a step */
  onDeleteStep: (index: number) => void;
  /** Callback to rename a step */
  onRenameStep: (index: number, newTitle: string) => void;
  onStepConditionChange?: (index: number, condition: FormStep["showIf"]) => void;
  /** Hide all step controls (used in nested field editor) */
  hideStepControls?: boolean;
}

export function Canvas({
  fields,
  components,
  onEditField,
  onDeleteField,
  onConfigureNested,
  isDraggingFromPalette,
  className,
  steps,
  activeStepIndex,
  onActiveStepChange,
  onAddStep,
  onDeleteStep,
  onRenameStep,
  onStepConditionChange,
  hideStepControls,
}: CanvasProps) {
  const { setNodeRef, isOver } = useDroppable({
    id: "canvas",
  });

  const getComponent = (type: string) =>
    components.find((c) => c.type === type);

  // Filter fields by active step when there are multiple steps
  const visibleFields = useMemo(() => {
    if (steps.length <= 1) {
      // Single step mode - show all fields
      return fields;
    }
    // Multi-step mode - filter by activeStepIndex
    return fields.filter((f) => (f.stepGroup ?? 0) === activeStepIndex);
  }, [fields, steps.length, activeStepIndex]);

  // For sortable context, we only use visible fields
  const sortableItems = useMemo(() => visibleFields.map((f) => f.id), [visibleFields]);

  return (
    <div className={cn("flex flex-col h-full", className)}>
      {/* Step Tabs */}
      <StepTabs
        steps={steps}
        activeStepIndex={activeStepIndex}
        onActiveStepChange={onActiveStepChange}
        onAddStep={onAddStep}
        onDeleteStep={onDeleteStep}
        onRenameStep={onRenameStep}
        hideStepControls={hideStepControls}
      />

      {!hideStepControls && steps.length > 1 && onStepConditionChange && (
        <div className="mb-4">
          <p className="mb-2 text-sm font-medium">{steps[activeStepIndex]?.title} visibility</p>
          <ConditionEditor value={steps[activeStepIndex]?.showIf} onChange={condition => onStepConditionChange(activeStepIndex, condition)} fieldIds={fields.filter(field => (field.stepGroup ?? 0) < activeStepIndex).map(field => field.id)} />
        </div>
      )}
      {/* Canvas Drop Area */}
      <div
        ref={setNodeRef}
        data-testid="form-builder-canvas"
        className={cn(
          "flex-1 p-4 rounded-lg border-2 border-dashed min-h-[400px] transition-colors",
          isOver && isDraggingFromPalette
            ? "border-primary bg-primary/5"
            : "border-muted-foreground/20"
        )}
      >
        {visibleFields.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-full text-muted-foreground"  data-testid="canvas-drop-zone">
            <p className="text-lg font-medium">Drop components here</p>
            <p className="text-sm">
              {steps.length > 1
                ? `Drag components from the palette to add to ${steps[activeStepIndex]?.title || "this step"}`
                : "Drag components from the palette to build your form"}
            </p>
          </div>
        ) : (
          <SortableContext
            items={sortableItems}
            strategy={verticalListSortingStrategy}
          >
            <div className="flex flex-col gap-2">
              {/* Drop zone at the beginning */}
              <DropZone id="drop-zone-start" isDraggingFromPalette={isDraggingFromPalette} />

              {visibleFields.map((field, index) => (
                <div key={field.id} className="flex flex-col gap-2">
                  <SortableField
                    field={field}
                    index={index}
                    component={getComponent(field.type)}
                    onEdit={() => onEditField(field.id)}
                    onDelete={() => onDeleteField(field.id)}
                    onConfigureNested={onConfigureNested ? () => onConfigureNested(field.id) : undefined}
                  />
                  {/* Drop zone after each field */}
                  <DropZone id={`drop-zone-${field.id}`} isDraggingFromPalette={isDraggingFromPalette} />
                </div>
              ))}
            </div>
          </SortableContext>
        )}
      </div>
    </div>
  );
}

"use client";

import { useId } from "react";
import { Textarea } from "@/components/ui/textarea";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import type { ShowIfCondition } from "@/lib/form-visibility";

/** Edit one field or step visibility condition. */
export function ConditionEditor({ value, onChange, fieldIds }: {
  value?: ShowIfCondition;
  onChange: (condition: ShowIfCondition | undefined) => void;
  fieldIds: string[];
}) {
  const id = useId();
  const ValueInput = value?.operator === "in" ? Textarea : Input;
  return (
    <fieldset className="flex flex-col gap-3 rounded-md border p-3">
      <legend className="px-1 text-sm font-medium">Visibility</legend>
      <Label htmlFor={`${id}-field`}>Show if field</Label>
      <Select value={value?.field ?? "__always"} onValueChange={field => onChange(field === "__always" ? undefined : { field, operator: "isTruthy" })}>
        <SelectTrigger id={`${id}-field`}><SelectValue /></SelectTrigger>
        <SelectContent>
          <SelectItem value="__always">Always show</SelectItem>
          {fieldIds.map(field => <SelectItem key={field} value={field}>{field}</SelectItem>)}
        </SelectContent>
      </Select>
      {value && <>
        <Label htmlFor={`${id}-operator`}>Condition</Label>
        <Select value={value.operator} onValueChange={operator => onChange({ ...value, operator: operator as ShowIfCondition["operator"], value: operator === "in" ? [] : "" })}>
          <SelectTrigger id={`${id}-operator`}><SelectValue /></SelectTrigger>
          <SelectContent>
            <SelectItem value="equals">Equals</SelectItem>
            <SelectItem value="notEquals">Does not equal</SelectItem>
            <SelectItem value="in">Is one of</SelectItem>
            <SelectItem value="isTruthy">Has a truthy value</SelectItem>
          </SelectContent>
        </Select>
        {value.operator !== "isTruthy" && <>
          <Label htmlFor={`${id}-value`}>{value.operator === "in" ? "Values (one per line)" : "Value"}</Label>
          <ValueInput id={`${id}-value`} value={value.operator === "in" ? (Array.isArray(value.value) ? value.value.map(item => typeof item === "string" ? JSON.stringify(item) : String(item)).join("\n") : "") : typeof value.value === "string" ? value.value : JSON.stringify(value.value) ?? ""}
            onChange={event => {
              const parse = (text: string) => { try { return JSON.parse(text); } catch { return text; } };
              onChange({ ...value, value: value.operator === "in" ? event.target.value.split("\n").map(text => parse(text.trim())) : parse(event.target.value) });
            }} />
          <p className="text-xs text-muted-foreground">{value.operator === "in" ? "Enter one value per line. " : ""}Numbers, true and false are compared as typed values. Quote them to compare text.</p>
        </>}
      </>}
    </fieldset>
  );
}

"use client";

import { useCallback, useMemo, useState } from "react";
import AutoForm from "@/components/ui/auto-form";
import { buildFieldConfigFromJsonSchema } from "@/components/ui/auto-form/helpers";
import { ConditionEditor } from "./condition-editor";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import type {
  FormBuilderField,
  FormBuilderComponentDefinition,
  FormBuilderFieldProps,
  FormStep,
} from "./types";

interface EditFieldDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  field: FormBuilderField | null;
  component: FormBuilderComponentDefinition | null;
  onUpdate: (id: string, props: Partial<FormBuilderFieldProps>, newId?: string, stepGroup?: number) => void;
  /** Steps for multi-step forms */
  steps?: FormStep[];
  /** All existing field IDs for duplicate validation */
  allFieldIds?: string[];
}

export function EditFieldDialog({
  open,
  onOpenChange,
  field,
  component,
  onUpdate,
  steps = [],
  allFieldIds = [],
}: EditFieldDialogProps) {
  // Compute initial values when field or dialog state changes
  // We intentionally reset when `open` changes to reinitialize the form
  const initialValues = useMemo(() => {
    if (!field) return { fieldName: "", props: {}, key: "" };
    const values: Record<string, unknown> = { ...field.props };
    if (Array.isArray(values.options)) {
      values.options = (values.options as string[]).join("\n");
    }
    return { fieldName: field.id, props: values, key: `${field.id}-${open}` };
  }, [field, open]);

  // Track form values locally with overrides
  const [fieldNameOverride, setFieldNameOverride] = useState<string | null>(null);
  const [localPropsOverride, setLocalPropsOverride] = useState<Record<string, unknown> | null>(null);
  const [conditionOverride, setConditionOverride] = useState<{ value: FormBuilderFieldProps["showIf"] } | null>(null);
  const [stepGroupOverride, setStepGroupOverride] = useState<number | null>(null);

  // Use override if set, otherwise use initial values
  const fieldName = fieldNameOverride ?? initialValues.fieldName;
  const localProps = localPropsOverride ?? initialValues.props;
  const localStepGroup = stepGroupOverride ?? field?.stepGroup ?? 0;

  // Check for duplicate field ID (only when changing to a different ID)
  const isDuplicateId = useMemo(() => {
    if (!field || fieldName === field.id) return false;
    return allFieldIds.some((id) => id === fieldName && id !== field.id);
  }, [fieldName, field, allFieldIds]);

  // Reset overrides when initial values change
  const [prevInitial, setPrevInitial] = useState(initialValues);
  if (prevInitial !== initialValues) {
    setPrevInitial(initialValues);
    setFieldNameOverride(null);
    setLocalPropsOverride(null);
    setStepGroupOverride(null);
    setConditionOverride(null);
  }

  // Form key for AutoForm reset
  const formKey = initialValues.key;

  // Handle form value changes
  const handleValuesChange = useCallback(
    (values: Record<string, unknown>) => {
      setLocalPropsOverride(values);
    },
    []
  );

  // Handle save
  const handleSave = useCallback(() => {
    if (!field) return;

    // Handle special case for options (string to array)
    const props: Partial<FormBuilderFieldProps> = { ...localProps, showIf: conditionOverride ? conditionOverride.value : field.props.showIf };
    if (typeof props.options === "string") {
      props.options = (props.options as string)
        .split("\n")
        .map((s) => s.trim())
        .filter(Boolean);
    }

    // Determine if we need to update the ID
    const newId = fieldName !== field.id ? fieldName : undefined;

    // Determine if we need to update the step group
    // Only pass stepGroup if it was explicitly changed from the field's current value
    const stepGroup = stepGroupOverride !== null && stepGroupOverride !== field.stepGroup 
      ? stepGroupOverride 
      : undefined;

    // Single atomic update for props, ID, and step group
    onUpdate(field.id, props, newId, stepGroup);

    onOpenChange(false);
  }, [field, localProps, fieldName, onUpdate, onOpenChange, stepGroupOverride, conditionOverride]);

  if (!field || !component) {
    return null;
  }

  const Icon = component.icon as React.ComponentType<{ className?: string }>;

  // Build field config from the schema metadata
  const jsonSchema = component.propertiesSchema.toJSONSchema() as Record<string, unknown>;
  const fieldConfig = buildFieldConfigFromJsonSchema(jsonSchema);

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-md max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            {Icon && <Icon className="h-5 w-5 text-muted-foreground" />}
            Edit {component.label}
          </DialogTitle>
          <DialogDescription>
            Configure the properties for this field
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4 py-4">
          {/* Field Name */}
          <div className="space-y-2">
            <Label htmlFor="field-name">Field Name</Label>
            <Input
              id="field-name"
              value={fieldName}
              onChange={(e) => setFieldNameOverride(e.target.value)}
              placeholder="Enter field name"
              className={isDuplicateId ? "border-destructive focus-visible:ring-destructive" : ""}
              aria-invalid={isDuplicateId}
            />
            {isDuplicateId ? (
              <p className="text-xs text-destructive">
                A field with this name already exists. Please choose a different name.
              </p>
            ) : (
              <p className="text-xs text-muted-foreground">
                This is the key used in the form data and JSON schema
              </p>
            )}
          </div>

          {/* Step Selector (only shown when multiple steps exist) */}
          {steps.length > 1 && field && (
            <div className="space-y-2">
              <Label htmlFor="field-step">Step</Label>
              <Select
                value={String(localStepGroup)}
                onValueChange={(value) => setStepGroupOverride(parseInt(value, 10))}
              >
                <SelectTrigger id="field-step">
                  <SelectValue placeholder="Select step" />
                </SelectTrigger>
                <SelectContent>
                  {steps.map((step, index) => (
                    <SelectItem key={step.id} value={String(index)}>
                      {step.title}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <p className="text-xs text-muted-foreground">
                Which step this field belongs to
              </p>
            </div>
          )}

          <ConditionEditor value={conditionOverride ? conditionOverride.value : field.props.showIf} onChange={value => setConditionOverride({ value })} fieldIds={allFieldIds.filter(id => id !== field.id)} />

          {/* Properties Form */}
          <div className="border-t pt-4">
            <AutoForm
              key={formKey}
              formSchema={component.propertiesSchema}
              values={localProps}
              onValuesChange={handleValuesChange}
              fieldConfig={fieldConfig}
              className="space-y-4"
            />
          </div>
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            Cancel
          </Button>
          <Button onClick={handleSave} disabled={isDuplicateId}>
            Save Changes
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useState, useMemo } from "react";
import { SteppedAutoForm } from "@/components/ui/auto-form/stepped-auto-form";
import { buildFieldConfigFromJsonSchema } from "@/components/ui/auto-form/helpers";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import { formSchemaToZod } from "@/lib/schema-converter";
import type { JSONSchema } from "./types";
import type { AutoFormInputComponentProps } from "@/components/ui/auto-form/types";

interface FormPreviewProps {
  schema: JSONSchema;
  className?: string;
  /** 
   * Additional custom field components to use in the form preview.
   * These are merged with the default components (color picker, etc.).
   */
  fieldComponents?: Record<string, React.ComponentType<AutoFormInputComponentProps>>;
  /**
   * Default values to pre-populate the form with.
   * Useful for edit scenarios where the form should start with existing data.
   */
  defaultValues?: Record<string, unknown>;
}

export function FormPreview({ schema, className, fieldComponents, defaultValues }: FormPreviewProps) {
  const [submittedValues, setSubmittedValues] = useState<Record<string, unknown> | null>(null);

  // Create Zod schema from JSON Schema using the unified converter
  // This handles: steps metadata, stepGroup mapping, date constraints
  const zodSchema = useMemo(() => {
    try {
      if (!schema.properties || Object.keys(schema.properties).length === 0) {
        return null;
      }
      return formSchemaToZod(schema as unknown as Record<string, unknown>);
    } catch (error) {
      console.error("Failed to parse JSON Schema:", error);
      return null;
    }
  }, [schema]);

  // Custom field components for rendering (passed via props)
  const mergedFieldComponents = useMemo(() => fieldComponents ?? {}, [fieldComponents]);

  // Build field config from JSON Schema with custom components
  const fieldConfig = useMemo(() => {
    try {
      return buildFieldConfigFromJsonSchema(
        schema as unknown as Record<string, unknown>,
        mergedFieldComponents
      );
    } catch (error) {
      console.error("Failed to build field config:", error);
      return {};
    }
  }, [schema, mergedFieldComponents]);

  const handleSubmit = (values: unknown) => {
    setSubmittedValues(values as Record<string, unknown>);
  };

  const handleReset = () => {
    setSubmittedValues(null);
  };

  if (!zodSchema) {
    return (
      <div className={cn("p-8 text-center text-muted-foreground", className)}>
        <p className="text-lg font-medium mb-2">No fields to preview</p>
        <p className="text-sm">Add some fields to your form to see a preview</p>
      </div>
    );
  }

  return (
    <div className={cn("p-4 md:p-6", className)}>
      <div className="max-w-2xl mx-auto">
        {submittedValues ? (
          <div className="space-y-4">
            <div className="flex items-center justify-between">
              <h3 className="text-lg font-semibold">Submitted Values</h3>
              <Button variant="outline" onClick={handleReset}>
                Try Again
              </Button>
            </div>
            <div className="rounded-lg border bg-muted/50 p-4">
              <pre className="text-sm overflow-auto whitespace-pre-wrap">
                {JSON.stringify(submittedValues, null, 2)}
              </pre>
            </div>
          </div>
        ) : (
          <div className="space-y-6">
            <div className="text-center mb-6">
              <h3 className="text-lg font-semibold">Form Preview</h3>
              <p className="text-sm text-muted-foreground">
                Test your form and see the submitted values
              </p>
            </div>
            <div className="rounded-lg border bg-card p-6">
              <SteppedAutoForm
                formSchema={zodSchema}
                onSubmit={handleSubmit}
                fieldConfig={fieldConfig}
                values={defaultValues}
                submitButtonText="Submit"
              />
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import { useCallback, useId, useMemo, useState } from "react";
import {
  DndContext,
  DragOverlay,
  closestCenter,
  KeyboardSensor,
  PointerSensor,
  TouchSensor,
  useSensor,
  useSensors,
  type DragEndEvent,
  type DragStartEvent,
  type UniqueIdentifier,
} from "@dnd-kit/core";
import {
  arrayMove,
  sortableKeyboardCoordinates,
} from "@dnd-kit/sortable";
import { cn } from "@/lib/utils";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";

import { Palette, PaletteDragOverlay } from "./palette";
import { Canvas } from "./canvas";
import { EditFieldDialog } from "./edit-field-dialog";
import { NestedFieldEditorDialog } from "./nested-field-editor-dialog";
import { FormPreview } from "./form-preview";
import { FieldDragOverlay } from "./sortable-field";
import { defaultComponents, getComponentByType } from "./components";
import { fieldsToJSONSchema, jsonSchemaToFieldsAndSteps, generateFieldId, createStep } from "./schema-utils";
import type {
  FormBuilderComponentDefinition,
  FormBuilderField,
  FormBuilderFieldProps,
  FormStep,
  JSONSchema,
  DragData,
  PaletteDragData,
} from "./types";
import type { AutoFormInputComponentProps } from "@/components/ui/auto-form/types";

// Re-export types and components for external use
export { defaultComponents, objectFieldDefinition, arrayFieldDefinition } from "./components";
export { defineComponent } from "./types";
export { baseMetaSchema, baseMetaSchemaWithPlaceholder } from "./validation-schemas";
export type {
  FormBuilderComponentDefinition,
  FormBuilderField,
  FormBuilderFieldProps,
  JSONSchema,
  JSONSchemaProperty,
  StringFieldProps,
} from "./types";

interface FormBuilderProps {
  /** Available components to use in the form builder */
  components?: FormBuilderComponentDefinition[];
  /** Current form schema (JSON Schema format) */
  value?: JSONSchema;
  /** Callback when form schema changes */
  onChange?: (schema: JSONSchema) => void;
  /** Additional CSS classes */
  className?: string;
  /** 
   * Custom field components for the form preview.
   * Maps fieldType names to React components that render the field.
   * These are merged with the default custom components (like color picker).
   * 
   * @example
   * ```tsx
   * <FormBuilder
   *   fieldComponents={{
   *     rating: RatingComponent,
   *     signature: SignatureComponent,
   *   }}
   * />
   * ```
   */
  fieldComponents?: Record<string, React.ComponentType<AutoFormInputComponentProps>>;
  /**
   * Default values to pre-populate the form preview with.
   * Useful for edit scenarios where the form should start with existing data.
   * 
   * @example
   * ```tsx
   * <FormBuilder
   *   defaultValues={{
   *     username: "johndoe",
   *     email: "john@example.com",
   *   }}
   * />
   * ```
   */
  defaultValues?: Record<string, unknown>;
}

export function FormBuilder({
  components = defaultComponents,
  value,
  onChange,
  className,
  fieldComponents,
  defaultValues,
}: FormBuilderProps) {
  // Stable ID for DndContext to prevent hydration mismatch
  const dndContextId = useId();

  // Internal state - initialized from value prop if provided
  // Note: To reset fields from parent, use a key prop on FormBuilder
  const [fields, setFields] = useState<FormBuilderField[]>(() => {
    if (!value) return [];
    const { fields: parsedFields } = jsonSchemaToFieldsAndSteps(value, components);
    return parsedFields;
  });

  // Steps state for multi-step forms
  const [steps, setSteps] = useState<FormStep[]>(() => {
    if (!value) return [];
    const { steps: parsedSteps } = jsonSchemaToFieldsAndSteps(value, components);
    return parsedSteps;
  });

  // Active step index for canvas filtering
  const [activeStepIndex, setActiveStepIndex] = useState(0);

  const [editDialogFieldId, setEditDialogFieldId] = useState<string | null>(null);
  const [nestedEditorFieldId, setNestedEditorFieldId] = useState<string | null>(null);
  const [activeId, setActiveId] = useState<UniqueIdentifier | null>(null);

  // Notify onChange when fields or steps change
  const notifyChange = useCallback(
    (newFields: FormBuilderField[], newSteps?: FormStep[]) => {
      if (onChange) {
        const schema = fieldsToJSONSchema(newFields, components, newSteps ?? steps);
        onChange(schema);
      }
    },
    [onChange, components, steps]
  );

  // Get current JSON Schema for preview
  const currentSchema = useMemo(
    () => fieldsToJSONSchema(fields, components, steps),
    [fields, components, steps]
  );

  // Sensors for dnd-kit with touch support
  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: {
        distance: 8,
      },
    }),
    useSensor(TouchSensor, {
      activationConstraint: {
        // Use distance instead of delay for better compatibility with
        // automated testing tools and faster touch interactions
        distance: 8,
      },
    }),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    })
  );

  // Determine what's being dragged
  const activeDragData = useMemo(() => {
    if (!activeId) return null;

    const idStr = String(activeId);

    // Check if it's a palette item
    if (idStr.startsWith("palette-")) {
      const componentType = idStr.replace("palette-", "");
      return {
        type: "palette",
        componentType,
        component: getComponentByType(componentType, components),
      };
    }

    // Otherwise it's a field
    const field = fields.find((f) => f.id === idStr);
    if (field) {
      return {
        type: "field",
        field,
        component: getComponentByType(field.type, components),
      };
    }

    return null;
  }, [activeId, fields, components]);

  // Handle drag start
  const handleDragStart = (event: DragStartEvent) => {
    setActiveId(event.active.id);
  };

  // Handle drag end
  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;
    setActiveId(null);

    if (!over) return;

    const activeData = active.data.current as DragData | undefined;

    // Handle palette item drop
    if (activeData?.type === "palette") {
      const { componentType } = activeData as PaletteDragData;
      const component = getComponentByType(componentType, components);

      if (component) {
        const newField: FormBuilderField = {
          id: generateFieldId(componentType),
          type: componentType,
          props: {
            label: component.defaultProps.label || component.label,
            ...component.defaultProps,
          },
          // Assign to active step when in multi-step mode
          ...(steps.length > 1 ? { stepGroup: activeStepIndex } : {}),
        };

        // Determine insertion index based on where item was dropped
        let insertIndex = fields.length;
        const overId = String(over.id);

        if (overId === "drop-zone-start") {
          // Dropped at the beginning
          insertIndex = 0;
        } else if (overId.startsWith("drop-zone-")) {
          // Dropped after a specific field
          const fieldId = overId.replace("drop-zone-", "");
          const overIndex = fields.findIndex((f) => f.id === fieldId);
          if (overIndex !== -1) {
            insertIndex = overIndex + 1;
          }
        } else if (overId !== "canvas") {
          // Dropped directly on a field
          const overIndex = fields.findIndex((f) => f.id === overId);
          if (overIndex !== -1) {
            insertIndex = overIndex + 1;
          }
        }

        const newFields = [...fields];
        newFields.splice(insertIndex, 0, newField);
        setFields(newFields);
        notifyChange(newFields);
      }
      return;
    }

    // Handle field reorder
    if (activeData?.type === "field" && active.id !== over.id) {
      const oldIndex = fields.findIndex((f) => f.id === active.id);
      const newIndex = fields.findIndex((f) => f.id === over.id);

      if (oldIndex !== -1 && newIndex !== -1) {
        const newFields = arrayMove(fields, oldIndex, newIndex);
        setFields(newFields);
        notifyChange(newFields);
      }
    }
  };

  // Update field props (with optional ID change and step group)
  const handleUpdateField = useCallback(
    (id: string, props: Partial<FormBuilderFieldProps>, newId?: string, stepGroup?: number) => {
      // Validate that the new ID doesn't already exist on another field
      if (newId && newId !== id) {
        const idExists = fields.some((f) => f.id === newId && f.id !== id);
        if (idExists) {
          // Reject the update - duplicate ID would cause data loss
          console.warn(`Cannot rename field "${id}" to "${newId}": a field with that ID already exists`);
          return;
        }
      }

      const newFields = fields.map((f) => {
        if (f.id !== id) return f;
        const updated: FormBuilderField = { 
          ...f, 
          id: newId || f.id, 
          props: { ...f.props, ...props } 
        };
        // Only update stepGroup if explicitly provided (not undefined)
        if (stepGroup !== undefined) {
          updated.stepGroup = stepGroup;
        }
        return updated;
      });
      setFields(newFields);
      notifyChange(newFields);
    },
    [fields, notifyChange]
  );

  // Open edit dialog for a field
  const handleEditField = useCallback((id: string) => {
    setEditDialogFieldId(id);
  }, []);

  // Delete field
  const handleDeleteField = useCallback(
    (id: string) => {
      const newFields = fields.filter((f) => f.id !== id);
      setFields(newFields);
      notifyChange(newFields);
    },
    [fields, notifyChange]
  );

  // Open nested field editor for object/array fields
  const handleConfigureNested = useCallback((id: string) => {
    setNestedEditorFieldId(id);
  }, []);

  // Save nested fields (children for object, itemTemplate for array)
  const handleSaveNestedFields = useCallback(
    (fieldId: string, nestedFields: FormBuilderField[]) => {
      const newFields = fields.map((f) => {
        if (f.id !== fieldId) return f;

        if (f.type === "object") {
          return { ...f, children: nestedFields };
        } else if (f.type === "array") {
          return { ...f, itemTemplate: nestedFields };
        }
        return f;
      });
      setFields(newFields);
      notifyChange(newFields);
    },
    [fields, notifyChange]
  );

  // ============================================================================
  // STEP HANDLERS
  // ============================================================================

  // Add a new step
  const handleAddStep = useCallback(() => {
    const newStep = createStep(steps.length);
    const newSteps = [...steps, newStep];

    // If this is the second step, we need to assign all existing fields to step 0
    if (steps.length === 1) {
      const updatedFields = fields.map((f) => ({ ...f, stepGroup: 0 }));
      setFields(updatedFields);
      setSteps(newSteps);
      notifyChange(updatedFields, newSteps);
    } else if (steps.length === 0) {
      // First step - create two steps (Step 1 and Step 2)
      const firstStep = createStep(0);
      const secondStep = createStep(1);
      const bothSteps = [firstStep, secondStep];
      const updatedFields = fields.map((f) => ({ ...f, stepGroup: 0 }));
      setFields(updatedFields);
      setSteps(bothSteps);
      notifyChange(updatedFields, bothSteps);
    } else {
      setSteps(newSteps);
      notifyChange(fields, newSteps);
    }
  }, [steps, fields, notifyChange]);

  // Delete a step
  const handleDeleteStep = useCallback(
    (index: number) => {
      // Filter out fields belonging to the deleted step
      const fieldsWithoutDeleted = fields.filter((f) => f.stepGroup !== index);

      if (steps.length <= 2) {
        // Going from 2 steps to single-step mode
        // Remove stepGroup from remaining fields
        const updatedFields = fieldsWithoutDeleted.map((f) => {
          // eslint-disable-next-line @typescript-eslint/no-unused-vars
          const { stepGroup: _, ...rest } = f;
          return rest;
        });
        setFields(updatedFields);
        setSteps([]);
        setActiveStepIndex(0);
        notifyChange(updatedFields, []);
      } else {
        // Remove the step
        const newSteps = steps.filter((_, i) => i !== index);

        // Decrement stepGroup for fields after the deleted step
        const updatedFields = fieldsWithoutDeleted.map((f) => {
          if (f.stepGroup !== undefined && f.stepGroup > index) {
            return { ...f, stepGroup: f.stepGroup - 1 };
          }
          return f;
        });

        setFields(updatedFields);
        setSteps(newSteps);
        // Adjust active step if needed
        if (activeStepIndex >= newSteps.length) {
          setActiveStepIndex(newSteps.length - 1);
        }
        notifyChange(updatedFields, newSteps);
      }
    },
    [steps, fields, activeStepIndex, notifyChange]
  );

  // Rename a step
  const handleRenameStep = useCallback(
    (index: number, newTitle: string) => {
      const newSteps = steps.map((step, i) =>
        i === index ? { ...step, title: newTitle } : step
      );
      setSteps(newSteps);
      notifyChange(fields, newSteps);
    },
    [steps, fields, notifyChange]
  );

  // Get edit dialog field and its component
  const editDialogField = fields.find((f) => f.id === editDialogFieldId) || null;
  const editDialogComponent = editDialogField
    ? getComponentByType(editDialogField.type, components) || null
    : null;

  // Get nested editor field
  const nestedEditorField = fields.find((f) => f.id === nestedEditorFieldId) || null;

  return (
    <div className={cn("flex flex-col lg:h-full", className)}>
      <DndContext
        id={dndContextId}
        sensors={sensors}
        collisionDetection={closestCenter}
        onDragStart={handleDragStart}
        onDragEnd={handleDragEnd}
      >
        {/* Mobile: stack vertically and allow page scroll. Desktop: horizontal layout with overflow */}
        <div className="flex-1 flex flex-col lg:flex-row lg:overflow-hidden">
          {/* Palette */}
          <div className="w-full lg:w-64 p-4 border-b lg:border-b-0 lg:border-r lg:overflow-auto shrink-0">
            <Palette components={components} />
          </div>

          {/* Canvas */}
          <div className="flex-1 p-4 lg:overflow-auto min-h-[300px]">
            <Canvas
              fields={fields}
              components={components}
              onEditField={handleEditField}
              onDeleteField={handleDeleteField}
              onConfigureNested={handleConfigureNested}
              isDraggingFromPalette={activeDragData?.type === "palette"}
              steps={steps}
              activeStepIndex={activeStepIndex}
              onActiveStepChange={setActiveStepIndex}
              onAddStep={handleAddStep}
              onDeleteStep={handleDeleteStep}
              onRenameStep={handleRenameStep}
              onStepConditionChange={(index, showIf) => {
                const nextSteps = steps.map((step, i) => i === index ? { ...step, showIf } : step);
                setSteps(nextSteps);
                notifyChange(fields, nextSteps);
              }}
            />
          </div>

          {/* Right Panel with Tabs */}
          <div className="w-full flex-1 lg:w-96 border-t lg:border-t-0 lg:border-l lg:overflow-auto min-h-[300px]">
            <Tabs defaultValue="preview" className="h-full flex flex-col">
              <div className="p-4 border-b">
                <TabsList className="w-full">
                  <TabsTrigger value="preview" className="flex-1">
                    Preview
                  </TabsTrigger>
                  <TabsTrigger value="schema" className="flex-1">
                    JSON Schema
                  </TabsTrigger>
                </TabsList>
              </div>
              <TabsContent value="preview" className="flex-1 m-0 lg:overflow-auto">
                <FormPreview schema={currentSchema} fieldComponents={fieldComponents} defaultValues={defaultValues} />
              </TabsContent>
              <TabsContent value="schema" className="flex-1 m-0 p-4 lg:overflow-auto">
                <div className="rounded-lg border bg-muted/50 p-4">
                  <pre className="text-sm overflow-auto whitespace-pre-wrap">
                    {JSON.stringify(currentSchema, null, 2)}
                  </pre>
                </div>
              </TabsContent>
            </Tabs>
          </div>
        </div>

        {/* Drag Overlay */}
        <DragOverlay dropAnimation={null}>
          {activeDragData?.type === "palette" && activeDragData.component && (
            <PaletteDragOverlay component={activeDragData.component} />
          )}
          {activeDragData?.type === "field" && activeDragData.field && (
            <FieldDragOverlay
              field={activeDragData.field}
              component={activeDragData.component}
            />
          )}
        </DragOverlay>
      </DndContext>

      {/* Edit Field Dialog */}
      <EditFieldDialog
        open={editDialogFieldId !== null}
        onOpenChange={(open) => !open && setEditDialogFieldId(null)}
        field={editDialogField}
        component={editDialogComponent}
        onUpdate={handleUpdateField}
        steps={steps}
        allFieldIds={fields.map((f) => f.id)}
      />

      {/* Nested Field Editor Dialog */}
      <NestedFieldEditorDialog
        open={nestedEditorFieldId !== null}
        onOpenChange={(open) => !open && setNestedEditorFieldId(null)}
        field={nestedEditorField}
        components={components}
        onSave={handleSaveNestedFields}
      />
    </div>
  );
}

export default FormBuilder;

"use client";

import { useCallback, useId, useMemo, useState } from "react";
import { createPortal } from "react-dom";
import {
  DndContext,
  DragOverlay,
  closestCenter,
  KeyboardSensor,
  PointerSensor,
  TouchSensor,
  useSensor,
  useSensors,
  type DragEndEvent,
  type DragStartEvent,
  type UniqueIdentifier,
} from "@dnd-kit/core";
import { snapCenterToCursor } from "@dnd-kit/modifiers";
import {
  arrayMove,
  sortableKeyboardCoordinates,
} from "@dnd-kit/sortable";
import { FolderOpen, List } from "lucide-react";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Palette, PaletteDragOverlay } from "./palette";
import { Canvas } from "./canvas";
import { EditFieldDialog } from "./edit-field-dialog";
import { FieldDragOverlay } from "./sortable-field";
import { getComponentByType } from "./components";
import { generateFieldId } from "./schema-utils";
import type {
  FormBuilderComponentDefinition,
  FormBuilderField,
  FormBuilderFieldProps,
  DragData,
  PaletteDragData,
} from "./types";

interface NestedFieldEditorDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  /** The parent field being edited (object or array) */
  field: FormBuilderField | null;
  /** Available component definitions */
  components: FormBuilderComponentDefinition[];
  /** Callback when the nested fields are saved */
  onSave: (fieldId: string, nestedFields: FormBuilderField[]) => void;
}

export function NestedFieldEditorDialog({
  open,
  onOpenChange,
  field,
  components,
  onSave,
}: NestedFieldEditorDialogProps) {
  // Stable ID for nested DndContext
  const dndContextId = useId();

  // Get the nested fields based on field type
  const initialFields = useMemo(() => {
    if (!field) return [];
    if (field.type === "object") return field.children || [];
    if (field.type === "array") return field.itemTemplate || [];
    return [];
  }, [field]);

  // Local state for editing
  const [nestedFields, setNestedFields] = useState<FormBuilderField[]>(initialFields);
  const [activeId, setActiveId] = useState<UniqueIdentifier | null>(null);
  const [editDialogFieldId, setEditDialogFieldId] = useState<string | null>(null);

  // Reset local state when field changes or dialog opens
  const [prevField, setPrevField] = useState(field);
  const [prevOpen, setPrevOpen] = useState(open);
  if (prevField !== field || (open && !prevOpen)) {
    setPrevField(field);
    setPrevOpen(open);
    setNestedFields(initialFields);
    setEditDialogFieldId(null);
  }
  if (prevOpen !== open) {
    setPrevOpen(open);
  }

  // Sensors for dnd-kit
  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: { distance: 8 },
    }),
    useSensor(TouchSensor, {
      activationConstraint: { distance: 8 },
    }),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    })
  );

  // Determine what's being dragged
  const activeDragData = useMemo(() => {
    if (!activeId) return null;

    const idStr = String(activeId);

    // Check if it's a palette item
    if (idStr.startsWith("palette-")) {
      const componentType = idStr.replace("palette-", "");
      return {
        type: "palette",
        componentType,
        component: getComponentByType(componentType, components),
      };
    }

    // Otherwise it's a field
    const nestedField = nestedFields.find((f) => f.id === idStr);
    if (nestedField) {
      return {
        type: "field",
        field: nestedField,
        component: getComponentByType(nestedField.type, components),
      };
    }

    return null;
  }, [activeId, nestedFields, components]);

  // Handle drag start
  const handleDragStart = (event: DragStartEvent) => {
    setActiveId(event.active.id);
  };

  // Handle drag end
  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;
    setActiveId(null);

    if (!over) return;

    const activeData = active.data.current as DragData | undefined;

    // Handle palette item drop
    if (activeData?.type === "palette") {
      const { componentType } = activeData as PaletteDragData;
      const component = getComponentByType(componentType, components);

      if (component) {
        const newField: FormBuilderField = {
          id: generateFieldId(componentType),
          type: componentType,
          props: {
            label: component.defaultProps.label || component.label,
            ...component.defaultProps,
          },
        };

        // Determine insertion index
        let insertIndex = nestedFields.length;
        const overId = String(over.id);

        if (overId === "drop-zone-start") {
          insertIndex = 0;
        } else if (overId.startsWith("drop-zone-")) {
          const fieldId = overId.replace("drop-zone-", "");
          const overIndex = nestedFields.findIndex((f) => f.id === fieldId);
          if (overIndex !== -1) {
            insertIndex = overIndex + 1;
          }
        } else if (overId !== "canvas") {
          const overIndex = nestedFields.findIndex((f) => f.id === overId);
          if (overIndex !== -1) {
            insertIndex = overIndex + 1;
          }
        }

        const newFields = [...nestedFields];
        newFields.splice(insertIndex, 0, newField);
        setNestedFields(newFields);
      }
      return;
    }

    // Handle field reorder
    if (activeData?.type === "field" && active.id !== over.id) {
      const oldIndex = nestedFields.findIndex((f) => f.id === active.id);
      const newIndex = nestedFields.findIndex((f) => f.id === over.id);

      if (oldIndex !== -1 && newIndex !== -1) {
        setNestedFields(arrayMove(nestedFields, oldIndex, newIndex));
      }
    }
  };

  // Handle delete field
  const handleDeleteField = useCallback((id: string) => {
    setNestedFields((fields) => fields.filter((f) => f.id !== id));
  }, []);

  // Handle edit field - open the edit dialog
  const handleEditField = useCallback((id: string) => {
    setEditDialogFieldId(id);
  }, []);

  // Handle update field from edit dialog
  const handleUpdateField = useCallback(
    (id: string, props: Partial<FormBuilderFieldProps>, newId?: string) => {
      // Validate that the new ID doesn't already exist on another field
      if (newId && newId !== id) {
        const idExists = nestedFields.some((f) => f.id === newId && f.id !== id);
        if (idExists) {
          console.warn(`Cannot rename field "${id}" to "${newId}": a field with that ID already exists`);
          return;
        }
      }

      setNestedFields((fields) =>
        fields.map((f) => {
          if (f.id !== id) return f;
          return {
            ...f,
            id: newId || f.id,
            props: { ...f.props, ...props },
          };
        })
      );
    },
    [nestedFields]
  );

  // Handle save
  const handleSave = useCallback(() => {
    if (!field) return;
    onSave(field.id, nestedFields);
    onOpenChange(false);
  }, [field, nestedFields, onSave, onOpenChange]);

  if (!field) return null;

  const isObjectField = field.type === "object";
  const Icon = isObjectField ? FolderOpen : List;
  const fieldTypeLabel = isObjectField ? "Field Group" : "Repeating Group";
  const nestedLabel = isObjectField ? "nested fields" : "item fields";

  // Get edit dialog field and its component
  const editDialogField = nestedFields.find((f) => f.id === editDialogFieldId) || null;
  const editDialogComponent = editDialogField
    ? getComponentByType(editDialogField.type, components) || null
    : null;

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-6xl! max-h-[90vh] overflow-hidden flex flex-col">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Icon className="h-5 w-5 text-muted-foreground" />
            Configure {fieldTypeLabel}: {field.props.label}
          </DialogTitle>
          <DialogDescription>
            Add and arrange the {nestedLabel} for this {fieldTypeLabel.toLowerCase()}.
            {isObjectField
              ? " These fields will be grouped together."
              : " Each item in the array will have these fields."}
          </DialogDescription>
        </DialogHeader>

        <div className="flex-1 overflow-hidden">
          <DndContext
            id={dndContextId}
            sensors={sensors}
            collisionDetection={closestCenter}
            onDragStart={handleDragStart}
            onDragEnd={handleDragEnd}
          >
            <div className="flex h-[50vh] gap-4">
              {/* Palette */}
              <div className="w-48 overflow-auto shrink-0 border-r pr-4">
                <Palette components={components} />
              </div>

              {/* Canvas */}
              <div className="flex-1 overflow-auto">
                <Canvas
                  fields={nestedFields}
                  components={components}
                  onEditField={handleEditField}
                  onDeleteField={handleDeleteField}
                  isDraggingFromPalette={activeDragData?.type === "palette"}
                  // Nested fields don't support steps - hide step controls entirely
                  steps={[]}
                  activeStepIndex={0}
                  onActiveStepChange={() => {}}
                  onAddStep={() => {}}
                  onDeleteStep={() => {}}
                  onRenameStep={() => {}}
                  hideStepControls
                />
              </div>
            </div>

            {/* Drag Overlay - rendered in portal to escape dialog's transform context */}
            {typeof document !== "undefined" &&
              createPortal(
                <DragOverlay dropAnimation={null} modifiers={[snapCenterToCursor]}>
                  {activeDragData?.type === "palette" && activeDragData.component && (
                    <PaletteDragOverlay component={activeDragData.component} />
                  )}
                  {activeDragData?.type === "field" && activeDragData.field && (
                    <FieldDragOverlay
                      field={activeDragData.field}
                      component={activeDragData.component}
                    />
                  )}
                </DragOverlay>,
                document.body
              )}
          </DndContext>
        </div>

        <DialogFooter className="border-t pt-4">
          <div className="flex items-center gap-2 text-sm text-muted-foreground mr-auto">
            {nestedFields.length} {nestedFields.length === 1 ? "field" : "fields"}
          </div>
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            Cancel
          </Button>
          <Button onClick={handleSave}>Save Fields</Button>
        </DialogFooter>
      </DialogContent>

      {/* Edit Field Dialog for nested fields */}
      <EditFieldDialog
        open={editDialogFieldId !== null}
        onOpenChange={(open) => !open && setEditDialogFieldId(null)}
        field={editDialogField}
        component={editDialogComponent}
        onUpdate={handleUpdateField}
        steps={[]}
        allFieldIds={nestedFields.map((f) => f.id)}
      />
    </Dialog>
  );
}

"use client";

import { useDraggable } from "@dnd-kit/core";
import { cn } from "@/lib/utils";
import type { FormBuilderComponentDefinition, PaletteDragData } from "./types";

interface PaletteItemProps {
  component: FormBuilderComponentDefinition;
}

function PaletteItem({ component }: PaletteItemProps) {
  const { attributes, listeners, setNodeRef, isDragging } = useDraggable({
    id: `palette-${component.type}`,
    data: {
      type: "palette",
      componentType: component.type,
    } satisfies PaletteDragData,
  });

  const Icon = component.icon as React.ComponentType<{ className?: string }>;

  return (
    <div
      ref={setNodeRef}
      {...listeners}
      {...attributes}
      className={cn(
        "flex items-center gap-3 p-3 rounded-lg border bg-card cursor-grab active:cursor-grabbing",
        "hover:bg-accent hover:border-accent-foreground/20 transition-colors",
        "touch-none select-none",
        isDragging && "opacity-50"
      )}
    >
      {Icon && <Icon className="h-4 w-4 text-muted-foreground shrink-0" />}
      <span className="text-sm font-medium">{component.label}</span>
    </div>
