import AutoFormCheckbox from "./fields/checkbox";
import AutoFormDate from "./fields/date";
import AutoFormEnum from "./fields/enum";
import AutoFormInput from "./fields/input";
import AutoFormNumber from "./fields/number";
import AutoFormRadioGroup from "./fields/radio-group";
import AutoFormSwitch from "./fields/switch";
import AutoFormTextarea from "./fields/textarea";

export const INPUT_COMPONENTS = {
  file: AutoFormFile,
  checkbox: AutoFormCheckbox,
  date: AutoFormDate,
  select: AutoFormEnum,
  radio: AutoFormRadioGroup,
  switch: AutoFormSwitch,
  textarea: AutoFormTextarea,
  number: AutoFormNumber,
  fallback: AutoFormInput,
};

/**
 * Define handlers for specific Zod types.
 * You can expand this object to support more types.
 * 
 * Supports both:
 * - Zod v3 style: "ZodBoolean", "ZodEnum", etc. (from _def.typeName)
 * - Zod v4 style: "boolean", "enum", etc. (from _def.type)
 */
export const DEFAULT_ZOD_HANDLERS: {
  [key: string]: keyof typeof INPUT_COMPONENTS;
} = {
  // Zod v3 style type names
  ZodBoolean: "checkbox",
  ZodDate: "date",
  ZodEnum: "select",
  ZodNativeEnum: "select",
  ZodNumber: "number",
  // Zod v4 style type names (lowercase, no "Zod" prefix)
  boolean: "checkbox",
  date: "date",
  enum: "select",
  nativeEnum: "select",
  number: "number",
  int: "number",
  float: "number",
};

import type { FieldValues, UseFormWatch } from "react-hook-form";
import type { Dependency, EnumValues } from "./types";
import { DependencyType } from "./types";
import * as z from "zod";

export default function resolveDependencies<
  SchemaType extends z.infer<z.ZodObject<any, any>>,
>(
  dependencies: Dependency<SchemaType>[],
  currentFieldName: keyof SchemaType,
  watch: UseFormWatch<FieldValues>,
) {
  let isDisabled = false;
  let isHidden = false;
  let isRequired = false;
  let overrideOptions: EnumValues | undefined;

  const currentFieldValue = watch(currentFieldName as string);

  const currentFieldDependencies = dependencies.filter(
    (dependency) => dependency.targetField === currentFieldName,
  );
  for (const dependency of currentFieldDependencies) {
    const watchedValue = watch(dependency.sourceField as string);

    const conditionMet = dependency.when(watchedValue, currentFieldValue);

    switch (dependency.type) {
      case DependencyType.DISABLES:
        if (conditionMet) {
          isDisabled = true;
        }
        break;
      case DependencyType.REQUIRES:
        if (conditionMet) {
          isRequired = true;
        }
        break;
      case DependencyType.HIDES:
        if (conditionMet) {
          isHidden = true;
        }
        break;
      case DependencyType.SETS_OPTIONS:
        if (conditionMet) {
          overrideOptions = dependency.options;
        }
        break;
    }
  }

  return {
    isDisabled,
    isHidden,
    isRequired,
    overrideOptions,
  };
}

import type { ShowIfCondition } from "@/lib/form-visibility";
import type { INPUT_COMPONENTS } from "./config";

// ============================================================================
// INPUT PROPS BY BACKING TYPE
// ============================================================================

/**
 * Common input props shared by all field types.
 */
export interface BaseInputProps {
  /** Whether the field is disabled */
  disabled?: boolean;
  /** Whether the field is read-only */
  readOnly?: boolean;
  /** Whether the field is required */
  required?: boolean;
  /** Whether to show the label (auto-form specific) */
  showLabel?: boolean;
}

/**
 * Input props for string-backed fields (text, email, password, url, phone, textarea).
 */
export interface StringInputProps extends BaseInputProps {
  /** Placeholder text */
  placeholder?: string;
  /** HTML input type (text, email, password, tel, url) */
  type?: "text" | "email" | "password" | "tel" | "url" | string;
  /** Default value */
  defaultValue?: string;
  /** Minimum length */
  minLength?: number;
  /** Maximum length */
  maxLength?: number;
  /** Regex pattern for validation */
  pattern?: string;
  /** Autocomplete hint */
  autoComplete?: string;
}

/**
 * Input props for number-backed fields.
 */
export interface NumberInputProps extends BaseInputProps {
  /** Placeholder text */
  placeholder?: string;
  /** Default value */
  defaultValue?: number;
  /** Minimum value */
  min?: number;
  /** Maximum value */
  max?: number;
  /** Step value for increment/decrement */
  step?: number;
}

/**
 * Input props for boolean-backed fields (checkbox, switch).
 */
export interface BooleanInputProps extends BaseInputProps {
  /** Default value */
  defaultValue?: boolean;
}

/**
 * Input props for date-backed fields.
 */
export interface DateInputProps extends BaseInputProps {
  /** Default value as ISO string or Date */
  defaultValue?: string | Date;
  /** Minimum date as ISO string */
  min?: string;
  /** Maximum date as ISO string */
  max?: string;
}

/**
 * Input props for enum-backed fields (select, radio).
 */
export interface EnumInputProps extends BaseInputProps {
  /** Placeholder text (for select) */
  placeholder?: string;
  /** Default value (must match one of the enum options) */
  defaultValue?: string;
}

/**
 * Union type of all input props by backing type.
 */
export type TypedInputProps = 
  | StringInputProps
  | NumberInputProps
  | BooleanInputProps
  | DateInputProps
  | EnumInputProps;

/**
 * Generic input props that accept any field type.
 * Use this when the backing type is not known at compile time.
 * 
 * This is the catch-all type used for runtime flexibility.
 */
export interface SerializableInputProps extends BaseInputProps {
  placeholder?: string;
  type?: string;
  defaultValue?: unknown;
  min?: number | string;
  max?: number | string;
  step?: number | string;
  minLength?: number;
  maxLength?: number;
  pattern?: string;
  autoComplete?: string;
  /** Allow additional props for extensibility */
  [key: string]: unknown;
}

// ============================================================================
// INPUT PROPS TYPE MAPPING
// ============================================================================

/**
 * Maps backing Zod types to their corresponding input props type.
 */
export interface InputPropsByBackingType {
  string: StringInputProps;
  number: NumberInputProps;
  boolean: BooleanInputProps;
  date: DateInputProps;
  enum: EnumInputProps;
}

/**
 * Get the correct input props type for a backing type.
 */
export type InputPropsFor<T extends keyof InputPropsByBackingType> = InputPropsByBackingType[T];

/**
 * Built-in field types supported by auto-form.
 */
export type AutoFormBuiltinFieldType = keyof typeof INPUT_COMPONENTS;

/**
 * Field types that can be specified in JSON Schema.
 * Either a built-in type name or a custom component.
 */
export type FieldType = 
  | AutoFormBuiltinFieldType
  | (string & {});  // allow any string for extensibility

/**
 * JSON Schema property with form-builder and auto-form metadata.
 * 
 * This is the intermediate format used when:
 * - form-builder serializes field configurations
 * - auto-form parses JSON Schema to build field configs
 */
export interface JSONSchemaPropertyBase {
  /** Show this field only when its sibling condition matches. */
  showIf?: ShowIfCondition;
  // ========================
  // Standard JSON Schema
  // ========================
  /** JSON Schema type */
  type?: "string" | "number" | "integer" | "boolean" | "object" | "array" | "null";
  /** Human-readable title (JSON Schema standard) */
  title?: string;
  /** Description text */
  description?: string;
  /** Default value */
  default?: unknown;
  /** Enum values for select/radio fields */
  enum?: (string | number | boolean | null)[];
  /** Minimum value for numbers */
  minimum?: number;
  /** Maximum value for numbers */
  maximum?: number;
  /** Exclusive minimum for numbers */
  exclusiveMinimum?: number;
  /** Exclusive maximum for numbers */
  exclusiveMaximum?: number;
  /** Minimum length for strings */
  minLength?: number;
  /** Maximum length for strings */
  maxLength?: number;
  /** Regex pattern for strings */
  pattern?: string;
  /** Format hint (email, uri, date-time, etc.) */
  format?: string;
  /** Multiple of constraint for numbers */
  multipleOf?: number;

  // ========================
  // Nested structures
  // ========================
  /** Properties for object types */
  properties?: Record<string, JSONSchemaPropertyBase>;
  /** Required fields for object types */
  required?: string[];
  /** Additional properties allowed for objects */
  additionalProperties?: boolean;
  /** Item schema for array types */
  items?: JSONSchemaPropertyBase;

  // ========================
  // Form metadata (via Zod .meta())
  // ========================
  /** Display label (form-builder/auto-form) */
  label?: string;
  /** Field type override (checkbox, date, select, radio, switch, textarea, etc.) */
  fieldType?: FieldType;
  /** Placeholder text */
  placeholder?: string;
  /** HTML input type (text, email, password, tel, etc.) */
  inputType?: string;
  /** Additional input props */
  inputProps?: SerializableInputProps;
  /** Display order */
  order?: number;

  // ========================
  // Date constraints (from zodToFormSchema)
  // ========================
  /** Minimum date as ISO string */
  formatMinimum?: string;
  /** Maximum date as ISO string */
  formatMaximum?: string;
}

/**
 * Field configuration item that auto-form uses to customize field rendering.
 * This is the target type when converting from JSON Schema.
 * 
 * Note: This is kept in sync with auto-form/types.ts FieldConfigItem
 */
export interface FieldConfigItemBase {
  /** Description text or React node */
  description?: React.ReactNode;
  /** Input props passed to the field component */
  inputProps?: SerializableInputProps;
  /** Display label */
  label?: string;
  /** Field type override */
  fieldType?: FieldType | React.ComponentType<unknown>;
  /** Wrapper component */
  renderParent?: (props: { children: React.ReactNode }) => React.ReactElement | null;
  /** Display order */
  order?: number;
}

/**
 * Mapping of JSON Schema property keys to FieldConfigItem keys.
 * Used when converting between formats.
 */
export const JSON_SCHEMA_TO_FIELD_CONFIG_MAP = {
  // Direct mappings
  label: "label",
  description: "description",
  fieldType: "fieldType",
  inputProps: "inputProps",
  order: "order",
  // Properties that go into inputProps
  placeholder: "inputProps.placeholder",
  inputType: "inputProps.type",
  default: "inputProps.defaultValue",
} as const;

"use client";
import { Form } from "@/components/ui/form";
import React, { useCallback, useState } from "react";
import type {
  DefaultValues,
  FormState,
  UseFormReturn,
} from "react-hook-form";
import { useForm, useWatch } from "react-hook-form";
import { resolveVisibleSchema } from "@/lib/schema-converter";
import { z } from "zod";

import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import { zodResolver } from "@hookform/resolvers/zod";

import { FileUploadStatusContext } from "./fields/file";
import AutoFormObject from "./fields/object";
import type { Dependency, FieldConfig } from "./types";
import type { ZodObjectOrWrapped } from "./helpers";
import { getDefaultValues, getObjectFormSchema } from "./helpers";

export function AutoFormSubmit({
  children,
  className,
  disabled,
}: {
  children?: React.ReactNode;
  className?: string;
  disabled?: boolean;
}) {
  return (
    <Button type="submit" disabled={disabled} className={className}>
      {children ?? "Submit"}
    </Button>
  );
}

function AutoForm<SchemaType extends ZodObjectOrWrapped>({
  formSchema,
  values: valuesProp,
  onValuesChange: onValuesChangeProp,
  onParsedValuesChange,
  onSubmit: onSubmitProp,
  fieldConfig,
  children,
  className,
  dependencies,
}: {
  formSchema: SchemaType;
  values?: Partial<z.infer<SchemaType>>;
  onValuesChange?: (
    values: Partial<z.infer<SchemaType>>,
    form: UseFormReturn<z.infer<SchemaType>>
  ) => void;
  onParsedValuesChange?: (
    values: Partial<z.infer<SchemaType>>,
    form: UseFormReturn<z.infer<SchemaType>>
  ) => void;
  onSubmit?: (
    values: z.infer<SchemaType>,
    form: UseFormReturn<z.infer<SchemaType>>
  ) => void;
  fieldConfig?: FieldConfig<z.infer<SchemaType>>;
  children?:
    | React.ReactNode
    | ((formState: FormState<z.infer<SchemaType>>) => React.ReactNode);
  className?: string;
  dependencies?: Dependency<z.infer<SchemaType>>[];
}) {
  const objectFormSchema = getObjectFormSchema(formSchema);
  const defaultValues: DefaultValues<z.infer<typeof objectFormSchema>> | null =
    getDefaultValues(objectFormSchema, fieldConfig);

  const form = useForm<Record<string, unknown>>({
    // Cast to any to handle Zod v4 type compatibility with @hookform/resolvers
    resolver: zodResolver(formSchema as any) as any,
    defaultValues: (defaultValues ?? undefined) as any,
    values: valuesProp as any,
  });

  const [uploadStatuses, setUploadStatuses] = useState<Record<string, "uploading" | "failed">>({});
  const reportUploadStatus = useCallback((name: string, status: "uploading" | "failed" | null) => {
    setUploadStatuses(previous => {
      if (previous[name] === status || (!status && !(name in previous))) return previous;
      const next = { ...previous };
      if (status) next[name] = status;
      else Reflect.deleteProperty(next, name);
      return next;
    });
  }, []);
  const uploading = Object.values(uploadStatuses).includes("uploading");
  const uploadBlocked = Object.keys(uploadStatuses).length > 0;
  const watchedValues = useWatch({ control: form.control });
  const metadata = formSchema.meta();
  const visibleKeys = metadata?.properties ? Object.keys(resolveVisibleSchema(metadata, watchedValues).schema.properties ?? {}) : null;
  const visibleObjectSchema = visibleKeys ? objectFormSchema.pick(Object.fromEntries(visibleKeys.map(key => [key, true]))) : objectFormSchema;

  const [schemaSubmitError, setSchemaSubmitError] = useState<string | null>(null);

  function onSubmit(values: Record<string, unknown>) {
    setSchemaSubmitError(null);
    const parsedValues = formSchema.safeParse(values);
    if (parsedValues.success) {
      onSubmitProp?.(parsedValues.data as z.infer<SchemaType>, form as any);
    } else {
      const message = parsedValues.error.issues
        .map(
          (issue) =>
            `${issue.path.length ? `${issue.path.join(".")}: ` : ""}${issue.message}`,
        )
        .join(" · ");
      setSchemaSubmitError(message);
    }
  }

  React.useEffect(() => {
    const subscription = form.watch((values) => {
      onValuesChangeProp?.(values as any, form as any);
      const parsedValues = formSchema.safeParse(values);
      if (parsedValues.success) {
        onParsedValuesChange?.(parsedValues.data as any, form as any);
      }
    });

    return () => subscription.unsubscribe();
  }, [form, formSchema, onValuesChangeProp, onParsedValuesChange]);

  const renderChildren =
    typeof children === "function"
      ? children(form.formState as FormState<z.infer<SchemaType>>)
      : children;

  return (
    <div className="w-full">
      <Form {...form}>
        <form
          onSubmit={(e) => {
            if (uploadBlocked) {
              e.preventDefault();
              setSchemaSubmitError(uploading ? "Wait for the upload to finish." : "Retry the failed file upload before submitting.");
              return;
            }
            form.handleSubmit(onSubmit, () => setSchemaSubmitError(null))(e);
          }}
          className={cn("space-y-5", className)}
        >
          <FileUploadStatusContext.Provider value={reportUploadStatus}>
          <fieldset disabled={uploading} className="contents">
          <AutoFormObject
            schema={visibleObjectSchema}
            form={form as any}
            dependencies={dependencies as any}
            fieldConfig={fieldConfig as any}
          />

          {schemaSubmitError ? (
            <div
              role="alert"
              className="rounded-md border border-destructive/50 bg-destructive/10 p-3 text-sm text-destructive"
            >
              {schemaSubmitError}
            </div>
          ) : null}

          {renderChildren}
          </fieldset>
          </FileUploadStatusContext.Provider>
        </form>
      </Form>
    </div>
  );
}

export default AutoForm;

import {
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from "@/components/ui/accordion";
import { Button } from "@/components/ui/button";
import {
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { Separator } from "@/components/ui/separator";
import { Plus, Trash } from "lucide-react";
import { useFieldArray, useForm, useWatch } from "react-hook-form";
import * as z from "zod";
import { beautifyObjectName, getBaseSchema, getBaseType } from "../helpers";
import AutoFormObject from "./object";

function getDefType(schema: z.ZodType): string {
  return (schema as any)._zod?.def?.type || "";
}

function getArrayElementType(item: z.ZodType): z.ZodType | null {
  const def = (item as any)._zod?.def;
  const defType = getDefType(item);

  if (defType === "array") {
    return def?.element || null;
  }

  if (["default", "optional", "nullable"].includes(defType)) {
    const innerType = def?.innerType;
    if (innerType) {
      return getArrayElementType(innerType);
    }
  }

  return null;
}

function getPrimitiveDefault(itemSchema: z.ZodType): unknown {
  const base = getBaseSchema(itemSchema as z.ZodType);
  if (!base) return "";
  switch (getBaseType(base)) {
    case "ZodBoolean":
      return false;
    case "ZodNumber":
      return 0;
    default:
      return "";
  }
}

export default function AutoFormArray({
  name,
  item,
  form,
  path = [],
  fieldConfig,
}: {
  name: string;
  item: z.ZodArray<any> | z.ZodDefault<any>;
  form: ReturnType<typeof useForm>;
  path?: string[];
  fieldConfig?: any;
}) {
  const itemDefType = getArrayElementType(item);
  const elementBaseSchema = itemDefType
    ? getBaseSchema(itemDefType as z.ZodType)
    : null;
  const elementPrimitiveType = elementBaseSchema
    ? getBaseType(elementBaseSchema as z.ZodType)
    : "";
  const isObjectArray = !!itemDefType && elementPrimitiveType === "ZodObject";

  const title = fieldConfig?.label ?? beautifyObjectName(name);

  if (isObjectArray) {
    return (
      <ObjectAutoFormArray
        name={name}
        item={item}
        form={form}
        path={path}
        fieldConfig={fieldConfig}
        itemDefType={itemDefType as z.ZodObject<any, any>}
        title={title}
      />
    );
  }

  return (
    <PrimitiveAutoFormArray
      name={name}
      item={item}
      form={form}
      path={path}
      fieldConfig={fieldConfig}
      itemDefType={itemDefType}
      title={title}
    />
  );
}

/**
 * ObjectAutoFormArray — uses useFieldArray (safe for object arrays because
 * react-hook-form only wraps objects; the `id` field it injects doesn't affect
 * validation since the schema doesn't include it).
 */
function ObjectAutoFormArray({
  name,
  form,
  path = [],
  fieldConfig,
  itemDefType,
  title,
}: {
  name: string;
  item: z.ZodArray<any> | z.ZodDefault<any>;
  form: ReturnType<typeof useForm>;
  path?: string[];
  fieldConfig?: any;
  itemDefType: z.ZodObject<any, any>;
  title: string;
}) {
  const fieldPath = path.join(".");
  const { fields, append, remove } = useFieldArray({
    control: form.control,
    name: fieldPath,
  });

  return (
    <AccordionItem value={name} className="border-none">
      <AccordionTrigger>{title}</AccordionTrigger>
      <AccordionContent>
        {fields.map((_field, index) => {
          const key = _field.id;
          return (
            <div className="mt-4 flex flex-col" key={key}>
              <AutoFormObject
                schema={itemDefType}
                form={form}
                fieldConfig={fieldConfig}
                path={[...path, index.toString()]}
              />
              <div className="my-4 flex justify-end">
                <Button
                  variant="secondary"
                  size="icon"
                  type="button"
                  className="hover:bg-zinc-300 hover:text-black focus:ring-0 focus:ring-offset-0 focus-visible:ring-0 focus-visible:ring-offset-0 dark:bg-white dark:text-black dark:hover:bg-zinc-300 dark:hover:text-black dark:hover:ring-0 dark:hover:ring-offset-0 dark:focus-visible:ring-0 dark:focus-visible:ring-offset-0"
                  onClick={() => remove(index)}
                >
                  <Trash className="size-4" />
                </Button>
              </div>
              <Separator />
            </div>
          );
        })}
        <Button
          type="button"
          variant="secondary"
          onClick={() => append({})}
          className="mt-4 flex items-center"
        >
          <Plus className="mr-2" size={16} />
          Add
        </Button>
      </AccordionContent>
    </AccordionItem>
  );
}

/**
 * PrimitiveAutoFormArray — does NOT use useFieldArray.
 *
 * useFieldArray wraps every element in an object `{ id: "...", <value> }` which
 * corrupts primitive arrays (string[], number[], boolean[]). Instead we use
 * useWatch to observe the raw array and form.setValue to mutate it, keeping
 * the values as plain primitives that will pass Zod validation on submit.
 */
function PrimitiveAutoFormArray({
  name,
  item,
  form,
  path = [],
  fieldConfig,
  itemDefType,
  title,
}: {
  name: string;
  item: z.ZodArray<any> | z.ZodDefault<any>;
  form: ReturnType<typeof useForm>;
  path?: string[];
  fieldConfig?: any;
  itemDefType: z.ZodType | null;
  title: string;
}) {
  const fieldPath = path.join(".");
  const rawValues: unknown[] = useWatch({ control: form.control, name: fieldPath }) ?? [];
  const values = Array.isArray(rawValues) ? rawValues : [];

  const appendItem = () => {
    const def = itemDefType ? getPrimitiveDefault(itemDefType) : "";
    form.setValue(fieldPath as any, [...values, def] as any, {
      shouldDirty: true,
      shouldValidate: false,
    });
  };

  const removeItem = (index: number) => {
    const next = values.filter((_, i) => i !== index);
    form.setValue(fieldPath as any, next as any, {
      shouldDirty: true,
      shouldValidate: false,
    });
  };

  return (
    <AccordionItem value={name} className="border-none">
      <AccordionTrigger>{title}</AccordionTrigger>
      <AccordionContent>
        {values.map((_, index) => {
          const cellPath = `${fieldPath}.${index}`;
          return (
            <div className="mt-4 flex flex-col" key={`${fieldPath}-${index}`}>
              {itemDefType ? (
                <PrimitiveArrayRow
                  form={form}
                  itemSchema={itemDefType}
                  cellPath={cellPath}
                />
              ) : null}
              <div className="my-4 flex justify-end">
                <Button
                  variant="secondary"
                  size="icon"
                  type="button"
